INSERT INTO `jobs` (`id`, `job_code`, `job_code_prefix`, `job_code_number`, `client_code`, `job_title`, `slug`, `country`, `state_province`, `city`, `postal_code`, `workplace_type`, `workplace_type_other`, `timezone`, `job_type`, `job_type_other`, `experience`, `salary_rate`, `salary_from`, `salary_to`, `salary_unit_from`, `salary_unit_to`, `salary_currency`, `salary_type`, `salary_boe`, `industry`, `industry_other`, `job_description`, `key_skills`, `our_terms`, `open_date`, `close_date`, `status`, `views`, `created_by`, `created_at`, `updated_at`, `published_at`) VALUES
(53,	'AC19',	'AC',	19,	'ADSK-9512',	'GTM Program Manager',	'gtm-program-manager',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'10 - 15 years',	'Based on Experience',	'',	'',	'',	'',	'USD',	'Per Hour',	1,	'',	'',	'<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Role &amp; Responsibilities</strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Lead end-to-end transformation programs across Marketing, Sales, Customer Success, Operations, Product, and Technology teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Assess existing programs, governance structures, and stakeholder landscapes to establish clarity and execution momentum</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Translate strategic business priorities into executable program roadmaps and measurable outcomes</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Define program scope, objectives, success metrics, and deliverables in partnership with cross-functional teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Establish integrated program plans, governance models, operating cadences, milestone tracking, and executive reporting</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage cross-program dependencies, risks, and escalations</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Facilitate executive decision-making with clear recommendations, trade-offs, and action plans</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Build and maintain relationships with senior leaders and executive stakeholders</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drive accountability and collaboration across diverse teams without direct authority</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop and enhance PMO standards, methodologies, and best practices</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Mentor and coach program managers supporting key initiatives</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Continuously improve program management processes and operating models</span></li>\r\n</ul>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Project Overview</strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Role sits within the Go-to-Market Program Management Office (GTM PMO).</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Highly visible role focused on leading strategic transformation initiatives driving organizational growth, alignment, and operational excellence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ideal candidate combines consulting expertise with hands-on program leadership.</span></li>\r\n</ul>',	'<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">10+ years in Program Management, PMO leadership, management consulting, transformation leadership, strategy &amp; operations, or GTM transformation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Demonstrated success leading enterprise-scale, cross-functional transformation initiatives.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proven ability to manage complex programs from strategy through execution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience rapidly integrating into ongoing initiatives and creating structure and alignment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong influencing and stakeholder management skills across executive and senior leadership.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience establishing governance frameworks, executive reporting, and decision-making processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Exceptional communication, facilitation, negotiation, and presentation skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to thrive in ambiguous environments while balancing strategic thinking and execution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience driving mindset, skillset, and toolset changes across Sales, Marketing, and/or Customer Success organizations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree required.</span></li>\r\n</ul>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif;\"><strong><span style=\"font-size: 10pt;\">Nice-to-Haves</span></strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Master\'s degree preferred.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Certifications: PMP, Prosci Change Management, Facilitation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience managing multi-project programs using Airtable or similar PM platforms.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong PowerPoint skills; ability to create executive-level presentations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent executive communication and storytelling abilities.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-06-16',	'2026-07-14',	'closed',	60,	5,	'2026-06-16 16:04:31',	'2026-07-14 05:39:31',	'2026-06-16 16:04:31'),
(60,	'AC26',	'AC',	26,	'ADSK-9579',	'Senior Network DevOps Engineer',	'senior-network-devops-engineer',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'10 - 15 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">We are seeking an experienced <strong>Senior Network DevOps Engineer</strong> to help transform traditional enterprise networking into a modern, automated, cloud-native, and AI-driven infrastructure platform.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">In this role, you will design, automate, monitor, and optimize large-scale enterprise network environments across on-premises data centers and public cloud platforms. You\'ll collaborate with Network Engineering, Cloud, Security, Platform Engineering, and Architecture teams to build highly scalable, resilient, secure, and self-healing network services using Infrastructure-as-Code (IaC), DevOps practices, and Agentic AI technologies.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and develop network automation solutions using <strong>Python, Ansible, Terraform, and REST APIs</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build and maintain Infrastructure-as-Code (IaC) solutions for enterprise networking and cloud infrastructure.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Automate provisioning, configuration management, compliance validation, and remediation workflows.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop reusable automation modules, SDKs, and API integrations.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Implement GitOps and CI/CD pipelines for network and infrastructure deployments.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and manage cloud networking across <strong>AWS, Azure, and GCP</strong>, including:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">VPC/VNET</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Transit Gateway</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">VPN Connectivity</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Load Balancers</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">DNS Services</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud Firewalls</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Direct Connect / ExpressRoute</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build enterprise observability solutions using tools such as Grafana, Prometheus, Splunk, ELK, Dynatrace, OpenTelemetry, and InfluxDB.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop AI-powered operational workflows using LLMs, RAG architectures, AI Agents, and ChatOps platforms.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build intelligent automation for incident response, predictive analytics, and anomaly detection.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate security controls into CI/CD pipelines and support Zero Trust and DevSecOps initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with cross-functional engineering teams to improve platform reliability, automation, and operational excellence.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years (10+ years preferred) of experience in Enterprise Networking, Cloud Networking, Network Automation, DevOps, or Site Reliability Engineering.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong hands-on experience with <strong>Agentic AI development</strong> and AI-driven automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Expertise in <strong>Python</strong>, <strong>Ansible</strong>, Infrastructure-as-Code, and CI/CD pipelines.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience working with <strong>AWS AgentCore</strong> and cloud-native networking solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of cloud networking, including AWS, Azure, and/or GCP.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Git, REST APIs, automation frameworks, and Infrastructure-as-Code tools such as Terraform.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience implementing DevOps and DevSecOps best practices.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong troubleshooting, analytical, and problem-solving skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent communication and collaboration skills in distributed engineering environments.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with SD-WAN, SASE, enterprise firewalls, wireless networking, and network security automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience integrating observability platforms and monitoring solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to AI Operations (AIOps), LLMs, RAG frameworks, AI Agents, and intelligent automation platforms.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Zero Trust architecture and security automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building scalable automation frameworks for enterprise infrastructure.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Agentic AI Development</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Python &amp; Ansible</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">CI/CD &amp; DevOps Automation</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">AWS AgentCore</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud Networking (AWS/Azure/GCP)</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Infrastructure-as-Code (Terraform)</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Enterprise Network Automation</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-03',	'2026-07-31',	'closed',	150,	13,	'2026-07-03 05:05:09',	'2026-07-20 06:20:39',	'2026-07-03 05:05:31'),
(63,	'AC29',	'AC',	29,	'ADSK-9602',	'Technical Program Manager - GovCloud/FedRamp',	'technical-program-manager-govcloudfedramp',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'10 - 15 years',	'Based on Experience',	'',	'',	'',	'',	'USD',	'Per Hour',	1,	'',	'',	'<p class=\"isSelectedEnd\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are seeking an experienced <strong>Technical Program Manager (TPM)</strong> to lead the delivery of large-scale networking and infrastructure programs. The ideal candidate will have a strong background in networking technologies, cloud infrastructure, program management, and cross-functional leadership. Experience working in regulated cloud environments such as <strong>AWS GovCloud/FedRAMP</strong> is highly preferred.</span></p>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Key Responsibilities</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Lead end-to-end delivery of large-scale networking and infrastructure programs from planning through execution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collaborate with Engineering, Security, Compliance, and Operations teams to deliver scalable and secure network solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage program plans, milestones, dependencies, risks, and critical path activities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drive architecture discussions and coordinate technical execution across multiple workstreams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Plan and manage production cutovers, rollout strategies, rollback plans, and operational readiness.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Communicate program status, risks, and executive updates to leadership.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure projects meet compliance and audit requirements in regulated environments.</span></li>\r\n</ul>',	'<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">10+ years of experience as a Technical Program Manager, Infrastructure Program Manager, or similar role.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of enterprise networking concepts, including:</span>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Routing</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Firewalls</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Load Balancing</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">DNS</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hybrid Cloud Connectivity</span></li>\r\n</ul>\r\n</li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience managing large-scale infrastructure or networking programs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on experience with cloud platforms, preferably <strong>AWS</strong>, including <strong>AWS GovCloud/FedRAMP</strong> environments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong expertise in program planning, dependency management, RAID tracking, and executive reporting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proven ability to lead cross-functional teams without direct authority.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent communication, stakeholder management, and problem-solving skills.</span></li>\r\n</ul>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Preferred Qualifications</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience delivering projects in regulated or compliance-driven environments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with change management, production cutovers, and operational readiness planning.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience working with globally distributed engineering teams.</span></li>\r\n</ul>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Must-Have Skills</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Technical Program Management</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Enterprise Networking</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">AWS Cloud (AWS GovCloud/FedRAMP preferred)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Infrastructure Program Delivery</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Risk &amp; Dependency Management (RAID)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-Functional Leadership</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Executive Stakeholder Management</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Operational Cutover Planning</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-08',	'2026-08-05',	'closed',	127,	13,	'2026-07-08 17:52:54',	'2026-08-04 20:08:18',	'2026-07-08 17:53:03'),
(64,	'AC30',	'AC',	30,	'BLCK-5061',	'Legal Operations Specialist',	'legal-operations-specialist',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'3 - 6 years',	'Based on Experience',	'',	'',	'',	'',	'USD',	'Per Hour',	1,	'',	'',	'<p class=\"isSelectedEnd\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are seeking a detail-oriented <strong>Civil Process Specialist</strong> to join our team. In this role, you will be responsible for processing legal claims involving customer funds, including garnishments, levies, liens, information subpoenas, and 1099-K tax form corrections. The ideal candidate has excellent organizational skills, strong attention to detail, and the ability to work efficiently in a fast-paced environment while ensuring compliance with legal and regulatory requirements.</span></p>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Key Responsibilities</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Review and process garnishments, levies, liens, and information subpoenas for accuracy, completeness, and legal sufficiency.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Research customer accounts to determine whether funds are subject to legal actions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Restrain and release customer funds in accordance with legal requirements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Prepare and submit responses to creditors, taxing authorities, attorneys, and courts within required timelines.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Communicate professionally with customers and third parties regarding civil process matters.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain accurate case tracking and documentation, including escalations and resolutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Assist customers with 1099-K tax form corrections.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure compliance with internal policies and applicable legal requirements.</span></li>\r\n</ul>',	'<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong organizational, analytical, and time management skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent verbal and written communication skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">High attention to detail and reading comprehension.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to manage multiple priorities in a fast-paced environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proficiency with Google Docs and Google Sheets.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience processing <strong>garnishments, levies, liens, or legal subpoenas</strong> is highly preferred.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with <strong>1099-K tax form corrections</strong> is a plus.</span></li>\r\n</ul>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Preferred Skills</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience in banking, financial services, payment processing, or legal operations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with civil process documentation and regulatory requirements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong customer service and problem-solving skills.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-08',	'2026-08-05',	'closed',	17,	13,	'2026-07-08 18:20:54',	'2026-07-11 02:03:26',	'2026-07-08 18:21:05'),
(65,	'AC31',	'AC',	31,	'ADSK-9624',	'Workday Adaptive Planning Consultant',	'workday-adaptive-planning-consultant',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'3 - 8 years',	'Based on Experience',	'',	'',	'',	'',	'USD',	'Per Hour',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">We are seeking an experienced <strong>Workday Adaptive Planning Consultant</strong> with strong expertise in <strong>Workforce Planning (WFP)</strong> and <strong>Headcount Planning</strong> to support enterprise planning initiatives. The ideal candidate will have hands-on experience designing and implementing Adaptive Planning models, partnering with FP&amp;A and HR stakeholders, and delivering scalable workforce planning solutions with minimal supervision.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, build, and enhance <strong>Workday Adaptive Planning</strong> workforce and headcount planning models.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with FP&amp;A, HR Operations, and business stakeholders to gather requirements and deliver planning solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead or support Workday Adaptive Planning implementation and enhancement projects.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop workforce planning models using Adaptive Planning best practices.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate Adaptive Planning with enterprise systems such as Workday HCM, Snowflake, Power BI, and other financial applications.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Create process documentation, user guides, and deliver end-user training.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support planning, forecasting, reporting, and continuous process improvements.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with cross-functional teams to optimize workforce planning and reporting capabilities.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\"><strong>3&ndash;5+ years</strong> of hands-on experience with <strong>Workday Adaptive Planning</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven experience implementing or enhancing <strong>Workday Adaptive Planning</strong> solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong expertise in <strong>Workforce Planning</strong>, <strong>Headcount Planning</strong>, and financial planning models.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience partnering with <strong>FP&amp;A</strong>, <strong>HR Operations</strong>, or <strong>HR Systems</strong> teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience integrating Adaptive Planning with Workday HCM, Snowflake, Power BI, or similar enterprise applications.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent analytical, communication, and stakeholder management skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong experience creating process documentation and delivering user training.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday Adaptive Planning Certification.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in a high-growth SaaS or publicly traded company.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of financial planning, budgeting, forecasting, and workforce management processes.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday Adaptive Planning</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workforce Planning (WFP)</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Headcount Planning</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">FP&amp;A / HR Operations</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday HCM</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Financial Planning &amp; Forecasting</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Process Documentation &amp; User Training</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Stakeholder Management</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-09',	'2026-08-06',	'closed',	123,	13,	'2026-07-09 02:48:26',	'2026-07-28 19:05:28',	'2026-07-09 02:48:32'),
(67,	'AC34',	'AC',	34,	'ADSK-9598',	'Desktop Automation Engineer (Python)',	'desktop-automation-engineer-python-2',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'3 - 5 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate closely with Product Management, Experience Design, and Engineering to ensure that products, services, and capabilities are designed and created with the highest quality standards.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop, execute, improve, and document test plans, test cases, and test scripts to provide comprehensive and practical testing of our deliverables.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Perform both manual and automated testing to validate that products meet business requirements and consistently exceed customer expectations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Identify, track and report software defects, and work collaboratively with cross-functional teams to ensure timely resolution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Continuously improve testing processes, tools, and methodologies to maintain high quality standards in face of evolving complexity and interdependencies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Conduct functional and regression testing to uncover defects that may not be detected by existing test cases.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Primary Skills (Must Have):</strong> </span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\">Python/Java/Perl scripting, GUI test automation experience (Squish/Robot, preferably desktop), CI/CD pipeline experience (Azure DevOps, AWS, etc.)</span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Minimum:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Minimum 2+ years of proven experience in QA automation or software development with a focus on test automation in desktop software development, preferably on Windows and Linux.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proficiency in writing and maintaining test automation using Python/Java//Perl for large codebases.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid foundation in computer science, with knowledge of data structures, algorithms, and software design/architecture.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">B.Sc. or M.Sc. in Computer Science or related field, or equivalent practical experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Passion for quality and an understanding of the latest test automation technologies and frameworks.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent written and verbal communication skills in English.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exceptional team player with experience working on a scrum team developing desktop products; understand software and/or services architecture, development, and testing; understand Agile and Scaled Agile.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with professional-grade GUI test automation using Squish.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience working with automation frameworks that scale, using tools like Playwright, Robot Framework, or similar.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with AWS (Amazon Web Services), Azure or other equivalent public clouds.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of AI/ML fundamentals, algorithms, and related concepts.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of Alias, VRED, or other computer aided industrial design or 3D visualization software is a plus.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with automotive design and visualization is a plus.</span></li>\r\n</ul>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Top 3 Screening Criteria&nbsp;</strong></span></div>\r\n<ol class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Minimum 3 years of hands-on automation scripting experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">CI/CD pipeline integration experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Python + Robot Framework <strong>or</strong> Java + Selenium experience</span></li>\r\n</ol>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	182,	1,	'2026-07-12 04:30:56',	'2026-07-14 05:34:49',	'2026-07-12 04:30:56'),
(68,	'AC36',	'AC',	36,	'ADSK-9584',	'Business Systems Analyst – SAP S2P/P2P',	'business-systems-analyst-sap-s2pp2p',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 8 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Own end-to-end business analysis: requirements gathering, process design, configuration support, testing, deployment, and post-go-live support across S2P and P2P solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with business stakeholders to understand procurement needs across intake, sourcing, supplier onboarding, purchasing, invoice processing, approvals, integrations, reporting, and compliance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Translate business requirements into user stories, functional specs, acceptance criteria, test scenarios, process flows, and release documentation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support implementation and enhancement of procurement tools: intake-to-procure orchestration, supplier lifecycle management, sourcing, purchasing, invoicing, and ERP integrations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Apply hands-on S/4HANA S2P/P2P knowledge: PRs, POs, goods receipt, service entry, invoice processing, vendor master, account assignment, approvals, and finance/procurement integration touchpoints.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Serve as Scrum Master: facilitate sprint planning, stand-ups, backlog refinement, sprint reviews, retrospectives, impediment tracking, and delivery governance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with Product Owners to maintain a healthy backlog; ensure sprint commitments are defined, prioritized, and delivered.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Coordinate UAT, defect triage, release readiness, change management, stakeholder communications, and operational handover.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Identify opportunities to simplify processes, improve UX, automate manual work, strengthen controls, and drive continuous improvement.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5&ndash;8 years as a Business Systems Analyst, Functional Consultant, Product Analyst, or similar in enterprise procurement/finance/S2P technology.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong S2P/P2P functional expertise with hands-on S/4HANA Procurement experience and at least one platform: SAP Ariba, Coupa, ZIP, Levelpath, or comparable.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Implementation experience across: Intake &amp; Orchestration, Sourcing &amp; Supplier Management, Purchasing, Invoicing, and ERP integrations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Practical Agile/Scrum skills: user story writing, acceptance criteria, backlog management, sprint execution, estimation, release planning, stakeholder demos.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to bridge business and technology teams, facilitate workshops, document current/future-state processes, and recommend scalable solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cross-functional collaboration experience: Procurement, Finance, Legal, Enterprise Architecture, Security, Integration, external vendors, and implementation partners.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong communication, analytical, documentation, and stakeholder management skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree in Information Systems, Business Administration, Supply Chain, Computer Science, Finance, or related field.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Prior experience as a Scrum Master or Agile delivery lead.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Jira, Confluence, ServiceNow, Miro, Lucidchart, or similar tools.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Agile/Scrum certification; SAP, Ariba, Coupa, or procurement technology certifications.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'published',	256,	6,	'2026-07-12 04:36:18',	'2026-08-14 12:58:36',	'2026-07-12 04:36:18'),
(69,	'AC38',	'AC',	38,	'ADSK-9599',	'Endpoint Security Engineer (Patch Management)',	'endpoint-security-engineer-patch-management',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'7 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead the enterprise endpoint Patch and Vulnerability Management program.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop and maintain patch management policies, standards, and operational procedures.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Define patch prioritization based on CVSS scores, exploitability, threat intelligence, business criticality, and risk.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage OS and application patching across Windows, macOS, VMs, cloud platforms, firmware, and third-party software.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Coordinate emergency patch deployments for zero-day vulnerabilities and critical/high security incidents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate vulnerability scanning tools with patch management platforms to automate remediation workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with Infrastructure, Cloud, Platform Engineering, and Application teams to reduce remediation timelines.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and implement automated patch deployment pipelines using scripting and configuration management tools.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Monitor patch compliance, remediation SLAs, and vulnerability trends via dashboards and executive reporting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Perform root cause analysis for patch failures and recommend preventive improvements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support audits and regulatory compliance: ISO 27001, SOC 2, PCI DSS, HIPAA, NIST, Cyber Essentials Plus (Mandatory), and CIS Controls.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Evaluate emerging technologies and recommend improvements to enterprise patch management capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Mentor engineers and provide technical leadership across the organization.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree in Computer Science, Information Security, IT, or related field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7&ndash;10 years of experience in Infrastructure, Systems Engineering, Cybersecurity, or Vulnerability Management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years leading enterprise patch management programs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Deep knowledge of Windows Client OS, Linux, VMware, cloud platforms (AWS, Azure, GCP), and enterprise endpoint management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with at least one vulnerability management tool: Tenable, Qualys, Rapid7, InsightVM, or Microsoft Defender Vulnerability Management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Mandatory patch management tools: Microsoft Intune, JAMF, Automox.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong PowerShell scripting (Mandatory); Python and Bash also required.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience automating processes using Infrastructure as Code and configuration management tools.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid understanding of CVSS, MITRE ATT&amp;CK, and threat intelligence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience supporting large-scale enterprise environments with thousands of endpoints.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\">NinjaOne Patch Management, Kaseya VSA, ConnectWise Automate, Action1, SolarWinds Patch Manager.</span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Full Technical Skill Set:</strong></span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\">Vulnerability &amp; Patch Management, Linux Administration, Cloud Security (AWS, Azure, GCP), Microsoft Intune, JAMF, Tanium, BigFix, Ansible, PowerShell, Python, Bash, VMware, Active Directory, Microsoft Defender, Qualys, Tenable, Rapid7, ServiceNow, Automation, Risk Management.</span></p>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'published',	299,	6,	'2026-07-12 04:38:01',	'2026-08-14 18:19:25',	'2026-07-12 04:38:01'),
(70,	'AC40',	'AC',	40,	'ADSK-9572',	'NodeJS Developer (AWS)',	'nodejs-developer-aws',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'8 - 12 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead design, development, and evolution of scalable, secure, high-performance backend services using Node.js and TypeScript</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Drive architectural decisions and technical strategy across multiple teams and product areas</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Establish and promote engineering best practices: code quality, testing, documentation, and operational excellence</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and review distributed systems, microservices, APIs, and cloud-native solutions focused on scalability and reliability</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead cross-functional technical initiatives; collaborate with Architects, DevOps, Product, Security, and Support teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Translate complex business requirements into architectural designs, technical roadmaps, and execution plans</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Drive adoption of AI-assisted development tools and modern engineering practices</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Troubleshoot and resolve critical production issues; improve system reliability and performance</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Evaluate technologies, frameworks, and architectural patterns for long-term platform growth</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Mentor senior engineers, lead design reviews, foster a culture of technical excellence and continuous learning</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Influence engineering direction through architecture reviews, technical leadership, and strategic planning</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support operational excellence through incident reviews, reliability improvements, and production readiness initiatives</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">8&ndash;10 years overall software development experience; 6&ndash;7 years relevant experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s or Master\'s degree in Computer Science or related technical field</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong expertise in Node.js, TypeScript, and modern JavaScript frameworks (e.g., React)</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven experience designing and delivering large-scale distributed systems and microservices architectures</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building and governing REST and/or gRPC APIs</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Deep understanding of cloud-native architectures; hands-on AWS experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Comprehensive automated testing strategies: unit, integration, and end-to-end testing</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong knowledge of SQL and NoSQL databases, data modeling, and performance optimization</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Docker, Kubernetes, and CI/CD platforms (Jenkins, Spinnaker, or similar)</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience creating and reviewing technical design documentation: HLDS, LLDS, RFCs, architectural proposals</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong problem-solving, leadership, communication, and stakeholder management skills</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with AI-assisted development tools: Cursor, GitHub Copilot, prompt engineering</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with observability/monitoring platforms: Splunk, Dynatrace, Datadog, or OpenTelemetry</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	50,	6,	'2026-07-12 04:40:14',	'2026-07-14 05:37:35',	'2026-07-12 04:40:14'),
(71,	'AC42',	'AC',	42,	'ADSK-9521',	'UX Researcher',	'ux-researcher',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'3 - 5 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proactively leading, planning, and executing research with employees and internal stakeholders to help teams design and improve business systems, services, and workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Employing a range of research methods, including usability studies, interviews, contextual inquiry, quantitative approaches (e.g., survey design, experimentation, and behavioral analytics), and more.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrating AI-powered tools and workflows (e.g., automated synthesis, LLM-assisted analysis, research repositories) to accelerate research throughput and uncover deeper insights at scale, while maintainingawareness of the underlying insights in order to speak to your research deeply and with confidence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Communicating, presenting, and documenting research findings in a clear and compelling way to product, design, engineering, and business stakeholders, including capturing key learnings in shared repositories so they can be easily found and understood by others.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Moving beyond &ldquo;what&rdquo; to supporting &ldquo;so what&rdquo; and &ldquo;now what,&rdquo; by identifying opportunity areas and translating insights into clear, actionable recommendations that influence design, product strategy, and workflow improvements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Facilitating empathy, journey mapping, and synthesis workshops with project teams and stakeholders to ensure that findings are translated into actionable improvements for employee experiences.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partnering closely with the Product team and Designer to align research goals with user needs, roadmap priorities, and business strategy.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partnering with other researchers on our team and with the broader research community to share best practices and feedback, share and evangelize research findings, collaborate on projects, and understand employees&rsquo; end-to-end journeys across systems and services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Supporting adjacent teams such as Service Design and Journey Management to ensure effective cataloging and application of insights in our journeymap platform, TheyDo.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partnering with data science, analytics, and business systems teams to define success metrics, interpret usage data, and triangulate findings across multiple data sources.</span></li>\r\n</ul>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">4+ years of professional research experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong track record of qualitative research influencing product, service, or workflow improvements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Demonstrated experience applying AI tools to research workflows (e.g., synthesis, insight generation, or repository management), with an understanding of limitations and bias considerations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Working knowledge of quantitative research methods, including survey design, basic statistical reasoning, and/or experimentation frameworks.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to collaborate with a wide set of stakeholders including designers, product managers, engineers, operations partners, and business system owners.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to execute in a fast-paced, agile environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent communication skills, with the ability to distill complex ideas to their essence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Demonstrated inquisitive mind and empathy for employees and internal users.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Value for collaboration and bringing people along with you.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Eagerness to work in complexity and derive simple, valuable solutions.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred: &nbsp;</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with tools used by employees we serve: Salesforce and Gainsight.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiary with tools we use in LEEP for research (e.g., Dovetail, UserTesting, Qualtrix, Outset.ai, WhatFix) and for documentation and sharing (e.g., Confluence, Airtable, TheyDo) </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience integrating qualitative and quantitative data to inform product, service, or operational strategy (mixed-methods research) </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with analytics tools and experience partnering with analytics teams to understand behavior across internal platforms.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with UX Research in an enterprise technology, business systems, or employee experience setting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with lean UX and lean research methodologies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with agile software development.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	145,	6,	'2026-07-12 04:41:03',	'2026-07-22 03:16:09',	'2026-07-12 04:41:03'),
(72,	'AC44',	'AC',	44,	'ADSK-2222',	'Teams Voice Engineer',	'teams-voice-engineer',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'8 - 11 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<div><span style=\"font-family: Lato, sans-serif;\">We are looking for an experienced Microsoft Teams Voice Expert to support the planning, design, implementation, migration, and operational support of Microsoft Teams Phone / MS Voice solutions. You will work with infrastructure, network, telecom, security, and end-user support teams to deliver reliable enterprise voice services across Microsoft Teams.The ideal candidate should have strong hands-on experience with Microsoft Teams Phone, Operator Connect, Calling Plans, SBC configuration, dial plans, voice routing policies, number management, and voice troubleshooting.</span></div>\r\n<div>\r\n<p><span style=\"font-family: Lato, sans-serif;\">The contractor will assess current telephony environments and design Microsoft Teams Voice solutions aligned with business, technical, and regulatory requirements. </span></p>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Voice Solution Design and Planning</strong></span></p>\r\n<ul>\r\n<li><span style=\"font-family: Lato, sans-serif;\">Create high-level and low-level design documentation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Define migration strategy, user waves, rollback approach, and support model.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Identify dependencies across networking, identity, licensing, security, endpoint devices, and telecom providers.</span></li>\r\n</ul>\r\n</div>\r\n<div><span style=\"font-family: Lato, sans-serif;\"><strong>Microsoft Teams Phone Implementation</strong></span></div>\r\n<div><span style=\"font-family: Lato, sans-serif;\">The contractor will configure and deploy Teams Phone capabilities using Microsoft Teams Admin Center and PowerShell. Microsoft documentation notes that voice routing policies can be managed in Teams Admin Center or PowerShell, and that Teams calling policies control calling and forwarding capabilities available to users.</span></div>\r\n<div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure Microsoft Teams Phone settings.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure users for enterprise voice and voicemail.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Assign Teams Phone licenses and calling policies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure dial plans and normalization rules.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure voice routing policies, routes, and emergency calling settings.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure call queues, auto attendants, resource accounts, shared lines, and common area phones where required.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support number assignment, number porting, number normalization, and lifecycle management.</span></li>\r\n</ul>\r\n</div>\r\n<div><span style=\"font-family: Lato, sans-serif;\"><strong>Operator Connect / Calling Plan Support</strong></span></div>\r\n<div><span style=\"font-family: Lato, sans-serif;\">The contractor will support Teams Phone deployments using Operator Connect or Microsoft Calling Plans where applicable. Operator Connect setup involves adding an operator and setting up numbers, including migration from Calling Plans or Direct Routing where needed.</span></div>\r\n<div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Coordinate with telecom providers and Microsoft-certified operators.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support number procurement, porting, assignment, and validation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Configure Operator Connect settings in Teams Admin Center.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Assist with migration from legacy PSTN, Calling Plans, or Direct Routing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Validate user calling, emergency calling, and regional dialing scenarios.</span></li>\r\n</ul>\r\n</div>\r\n<div><span style=\"font-family: Lato, sans-serif;\"><strong>Migration and Cutover Execution</strong></span></div>\r\n<div><span style=\"font-family: Lato, sans-serif;\">The contractor will help move users, sites, and numbers from legacy voice platforms to Microsoft Teams Phone.&nbsp;</span></div>\r\n<div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build migration runbooks and cutover checklists.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Execute pilot migrations and production migration waves.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Validate call flows before, during, and after cutover.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Coordinate with service desk, telecom carriers, network teams, and business stakeholders.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support rollback planning and issue resolution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Prepare user readiness and admin support documentation.</span></li>\r\n</ul>\r\n</div>\r\n<div><span style=\"font-family: Lato, sans-serif;\"><strong>Troubleshooting and Operations</strong></span></div>\r\n<div><span style=\"font-family: Lato, sans-serif;\">The contractor will provide advanced troubleshooting for voice quality, routing, and user calling issues.&nbsp;</span></div>\r\n<div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Troubleshoot failed calls, one-way audio, dropped calls, routing failures, and voicemail issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Analyze Teams Call Quality Dashboard, Call Analytics, SBC logs, SIP traces, and network data.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Investigate latency, jitter, packet loss, firewall, DNS, and QoS issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support incident, problem, and change management processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Recommend operational improvements and monitoring practices.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provide knowledge transfer to internal support teams.</span></li>\r\n</ul>\r\n</div>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5 to 8 years of strong hands-on experience with Microsoft Teams Phone / Microsoft Teams Voice.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Direct Routing, Operator Connect, and/or Microsoft Calling Plans.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience configuring voice routing policies, dial plans, normalization rules, calling policies, emergency calling, auto attendants, and call queues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of SIP, RTP/SRTP, TLS, DNS, certificates, codecs, firewalls, NAT, and QoS.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Session Border Controllers, preferably AudioCodes, Ribbon, Oracle, Cisco, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong Microsoft Teams Admin Center and Microsoft Teams PowerShell experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with number porting, number assignment, DID inventory, and telecom carrier coordination.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to troubleshoot complex enterprise voice issues using logs, traces, and analytics.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong documentation skills for designs, runbooks, support guides, and migration plans.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to work with global infrastructure, telecom, network, security, and end-user support teams.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Microsoft 365 / Teams Voice deployment experience in large enterprise environments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience migrating from legacy PBX platforms such as Cisco CUCM, Avaya, Genesys, Skype for Business, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with global voice deployments across multiple regions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of emergency calling requirements and location-based routing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Microsoft Entra ID, Exchange Online, Intune, endpoint management, and M365 licensing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Microsoft certifications such as MS-700, Microsoft Teams Administrator, or related Microsoft 365 certifications.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with ITIL-based incident, change, and problem management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience preparing executive-level migration status reports and technical readiness dashboards.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	26,	6,	'2026-07-12 04:42:55',	'2026-07-15 05:24:37',	'2026-07-12 04:42:55'),
(73,	'AC46',	'AC',	46,	'ADSK-9194',	'AWS Engineer (with AI)',	'aws-engineer-with-ai',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p><span style=\"font-family: Lato, sans-serif;\">We are seeking a hands-on Senior AI Engineer to design and build enterprise-grade Agentic AI applications within the AWS ecosystem.&nbsp;The ideal candidate should have strong Python development experience, practical exposure to Large Language Models (LLMs), and hands-on experience building Retrieval-Augmented Generation (RAG) and multi-agent workflows using frameworks such as LangChain/LangGraph or similar.&nbsp;This role focuses on designing, integrating, deploying, and operating AI-powered services on AWS, ensuring scalability, security, reliability, and cost efficiency.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and implement Agentic AI workflows using LLMs (OpenAI, Bedrock, or equivalent).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop Python-based backend services for: Model orchestration, Tool/function calling, Context management, API exposure.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build Retrieval-Augmented Generation (RAG) pipelines using vector databases (e.g., Pinecone, FAISS, OpenSearch).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design secure and scalable AI APIs using AWS services such as Lambda and API Gateway.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Deploy and manage AI workloads using AWS Bedrock and SageMaker.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Implement CI/CD pipelines and Infrastructure as Code (CloudFormation/CDK/Serverless Framework).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Apply MLOps best practices including: Model versioning, Prompt versioning, Monitoring and observability, Logging and performance tracking.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ensure AI systems are: Reliable and resilient, Secure (IAM, policies, encryption), Cost-aware and optimized.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with product owners, enterprise application teams, and data engineers to integrate AI solutions into business workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to AI use case evaluation and architecture design discussions.</span></li>\r\n</ul>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5&ndash;7 years of software engineering experience with strong Python expertise.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on experience integrating LLM platforms such as OpenAI or AWS Bedrock.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Practical experience building: RAG systems, Multi-agent or agentic workflows, Tool-calling or functioncalling architectures.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with frameworks such as: LangChain / LangGraph (or equivalent orchestration frameworks).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid experience with AWS services: Bedrock, SageMaker (model hosting/inference; full training expertise not mandatory), Lambda, ECS, S3, API Gateway, IAM etc.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience deploying applications using Infrastructure as Code (CloudFormation, CDK, Serverless Framework).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Understanding of: Prompt engineering, LLM limitations and guardrails, Context window management,Token optimization.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with vector databases and embedding workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong debugging, problem-solving, and system design skills.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing secure enterprise AI solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to SAP AI, enterprise ERP integration, or business process automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience implementing observability for AI systems (latency, hallucination tracking, usage monitoring).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with TypeScript for AI tooling or frontend integrations.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'published',	102,	6,	'2026-07-12 04:43:35',	'2026-08-14 12:58:40',	'2026-07-12 04:43:35'),
(74,	'AC48',	'AC',	48,	'ADSK-9259',	'Exchange Online & Teams Admin',	'exchange-online-teams-admin',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'8 - 12 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p><span style=\"font-family: Lato, sans-serif;\">We are seeking an experienced Messaging Administrator with strong expertise in Exchange Online and Microsoft Teams. The role involves handling operational support, troubleshooting issues, and ensuring seamless messaging and collaboration services.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provide L2 support for Exchange Online and Microsoft Teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Troubleshoot mail flow issues, mailbox access, and client connectivity problems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Basic administration of SharePoint Online.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Slack administration and integration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage and support: Mailboxes, shared mailboxes, distribution lists.Exchange transport rules and connectors.Teams&rsquo; policies, meetings, and calling features.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Monitor service health and proactively address incidents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Handle incident, service request, and problem management tickets.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Perform root cause analysis (RCA) for recurring issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ensure adherence to SLAs and operational procedures.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Train/assist the service desk team to improve FCR (First Contact resolution).</span></li>\r\n</ul>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong hands-on experience with:Exchange Online (mail flow, security, hybrid concepts).Microsoft Teams (policies, voice, collaboration features).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of PowerShell for M365 administration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Understanding of Microsoft 365 security and compliance basics.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to SendGrid (nice to have).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Miro Administration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Conference Room Operations Support.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Good to have skills:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Slack administration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Miro administration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Conference Room administration (MS Teams and Zoom). </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Airtable administration.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Soft Skills:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong troubleshooting and analytical skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to handle high-volume ticket environments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Good communication and documentation skills.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	295,	6,	'2026-07-12 04:44:45',	'2026-07-20 06:20:28',	'2026-07-12 04:44:45'),
(75,	'AC50',	'AC',	50,	'ADSK-9524',	'SAP R2R Product Owner',	'sap-r2r-product-owner-2',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Act as the Product Manager for SAP Finance R2R and Group Reporting capabilities, owning the roadmap, backlog, priorities, and stakeholder alignment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support SAP Record-to-Report (R2R) processes, including General Ledger, month-end close, journal entries, accruals, allocations, intercompany, and reconciliations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead SAP Group Reporting requirements, design, testing, and issue resolution for consolidation, financial reporting, entity hierarchies, eliminations, and close activities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with Finance, Controllership, and IT teams to translate business needs into SAP FI/CO product requirements, user stories, and functional designs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Drive UAT, regression testing, release readiness, controls, and continuous improvement for SAP R2R, FI/CO, and Group Reporting capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Good communication skills and stake holder manageremnt is required.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Around 7 years experience in product management .</span></li>\r\n</ul>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7&ndash;10 years of&nbsp;</span><span style=\"font-family: Lato, sans-serif;\">Product Owner / Product Management experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong communication and stakeholder management skills </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience using Jira</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to SAP </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work closely with engineering teams and product teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Write user stories and capture requirements</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ensure requirement clarity and execution by engineering teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage stakeholder communication</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Conduct demos where required</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage/coordinate with US-based team</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Candidates with no SAP exposure or no finance domain understanding will not be considered</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Procure-to-Revenue / Record-to-Revenue / Order-to-Cash flows</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Finance-related modules (FICO preferred but not mandatory)</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Candidates with hands-on experience in any SAP module who can learn FICO</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Candidates with finance domain exposure (GL, sub-ledger, group reporting)</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'closed',	59,	6,	'2026-07-12 04:46:43',	'2026-07-14 06:49:50',	'2026-07-12 04:46:43'),
(76,	'AC52',	'AC',	52,	'ADSK-9504',	'Salesforce JavaScript Developers',	'salesforce-javascript-developers',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'L',	'L',	'USD',	'Per Hour',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work in an Agile environment with a fun team to meet the project timelines.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop best in class high standard code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute in all the phases of software development cycles.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">BS with or MS in Computer Science or related technical field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Engineering Experience with at least 5+ years of experience in global software development and deployment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Must have 5+ years of experience with SFDC platform and partner ecosystem.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Must have experience in developing Lightning Components.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Played the role of a Technical lead in at least 2-3 SFDC projects.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Thorough knowledge of SFDC. Well versed in configuration, customization and Integration.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Primary Skills: </strong></span><span style=\"font-family: Lato, sans-serif;\">SFDC Admin &amp; Dev Experience, Visualforce, Visualforce templates, Apex, Async Apex, Apex trigger, LWC, Integration, SF Communities, Good understanding of SSO, GIT, Good understanding of CI/CD, AWS, Good understanding of Sales, Service and community cloud and excellent communication skills.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Salesforce Certified Platform Administrators (Must have).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Salesforce Certified JavaScript Developers (Must have).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Salesforce Certified Developer Platform Developer 1 (Must have).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Salesforce Certified Developer Platform Developer 2 (Optional).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience working with large scale enterprise organization with Front/Back Office.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Industry standard Repo tools like GIT.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Interaction with Client&rsquo;s key Business and Technical stakeholder for Solution Designing and Architecture.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven ability to manage and resolve complex and ambiguous technical issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Create Technical Documentation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Creativity C Critical Thinking.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent verbal and written communication skills.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Working Experience in CI/CD based deployment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Working Experience in a complex integrated environment where multiple systems interact with Salesforce.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in working with Salesforce connected apps.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-12',	'2026-08-09',	'published',	184,	6,	'2026-07-12 04:48:03',	'2026-08-14 12:58:30',	'2026-07-12 04:48:03'),
(79,	'AC56',	'AC',	56,	'ADSK-9421',	'NodeJS Backend Engineer',	'nodejs-backend-engineer',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and develop the O2P platform (web application + APIs)</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to DevOps functions for scalable, secure, and cost-effective customer-facing applications on AWS (Lambda, ECS, API Gateway, RDS).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proactively evaluate and adopt technology solutions for the O2P platform.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Apply strong Quality and DevOps practices to build maintainable and extensible solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build pragmatic, resilient solutions with consideration for upstream/downstream system impacts.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Champion unit testing across the team.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Engineering Excellence, Build &amp; Deploy, Operational Excellence, Recoverability &amp; Reliability.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with business stakeholders to translate use cases into functional and non-functional requirements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support production systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Mentor and collaborate with team members across APAC, EMEA, and the US.</span></li>\r\n</ul>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong JavaScript fundamentals. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong expertise in building RESTful microservices using Node.js.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">In-depth knowledge of frontend technologies and core web fundamentals.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building APIs and UIs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Good knowledge of API security, web security, and data encryption.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong architectural skills: scalable, available, resilient, cost-effective cloud application design (AWS preferred).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to select the right tech stack and tools for a given problem.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Comfortable with both Relational and NoSQL databases.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong DevOps and Quality mindset: CI/CD, Observability, Test Automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to clearly articulate technical experience, project contributions, responsibilities, and business impact.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong behavioural and communication skills: collaboration, teamwork, conflict resolution, stakeholder interaction.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience depth aligned with the seniority and complexity of the role.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Curious &amp; growth mindset; collaborative work style; effective communicator.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-13',	'2026-08-10',	'closed',	31,	8,	'2026-07-13 12:29:07',	'2026-07-14 05:37:41',	'2026-07-13 12:29:07'),
(80,	'AC57',	'AC',	57,	'ADSK-9622',	'React Developer',	'react-developer',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'7 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Member of a self-organized agile team building, owning, and operating Identity WebSDK capabilities and related cloud services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, develop, test, and maintain reusable JavaScript/TypeScript SDK capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build reliable, maintainable, type-safe frontend libraries and browser-based integrations across modern browsers.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design clean TypeScript interfaces, reusable abstractions, and developer-friendly APIs for multiple product teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to SDK architecture, implementation, testing, release quality, and long-term maintainability.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with backend Identity service teams on API, authentication flows, session behavior, error handling, and integration requirements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with product teams to support WebSDK adoption, troubleshoot integration issues, gather feedback, and improve developer experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to cloud service development including frontend, backend integration, DevOps, quality, monitoring, alerting, metrics, logging, and troubleshooting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Translate requirements into scalable technical solutions with senior engineers, architects, and product owners.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Identify continuous improvement opportunities in scalability, reliability, usability, security, and maintainability.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Participate in technical design reviews, code reviews, and architecture discussions.Help improve engineering practices, testing strategy, release quality, and team productivity.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree or equivalent in Computer Science or related technical field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7&ndash;10 years overall experience; 6+ years relevant software engineering with strong frontend development.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Deep understanding of JavaScript, TypeScript, HTML, CSS, and modern browser fundamentals.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building scalable, maintainable, reusable frontend code for complex web applications, shared libraries, or platform capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong TypeScript experience: type definitions, interfaces, generics, reusable abstractions, type-safe API design.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing reusable frontend abstractions and maintainable APIs across multiple teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of modern web standards, browser behavior, and cross-browser compatibility.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with modern frontend frameworks: React, Angular, Vue, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with frontend dev tools: Webpack, Babel, Vite, NPM, Yarn, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with TypeScript build tooling and type declarations for reusable frontend code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Frontend testing experience: unit, integration, and automation testing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with CI/CD practices (Jenkins a plus).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent analytical, troubleshooting, and debugging skills across complex multi-component systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid understanding of software design principles, architectural patterns, and maintainable/reusable code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building high-reliability, high-performance, scalable applications/libraries/services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven ability to write clean, maintainable, reusable, well-tested code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong collaboration and communication skills across engineers, architects, product owners, operations, support, and product teams.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building reusable JS/TS libraries, SDKs, shared platform capabilities, or developer-facing tools used by multiple teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with IAM concepts: authentication, authorization, user sessions, entitlements, SSO, MFA, user profile management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with identity standards: OAuth 2.0, OpenID Connect, JWT, PKCE, token refresh, session lifecycle management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with browser security: CORS, CSP, SameSite cookies, CSRF, XSS mitigation, secure token handling, redirect security, browser privacy constraints.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing developer-friendly APIs, reusable abstractions, migration paths, and backward-compatible interfaces.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building TypeScript packages with strong type declarations, clean module boundaries, and modern JS build targets.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">SDK/library release practices: semantic versioning, changelog generation, automated releases, package distribution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience creating/maintaining developer documentation, sample apps, integration/troubleshooting/migration guides.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience supporting adoption of shared platform capabilities across multiple product teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building privacy-conscious telemetry, diagnostics, logging, or observability for client-side libraries/SDKs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience leveraging or contributing to open-source projects.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-13',	'2026-08-10',	'closed',	8,	6,	'2026-07-13 15:22:48',	'2026-07-14 05:35:02',	'2026-07-13 15:22:48'),
(81,	'AC59',	'AC',	59,	'ADSK-6666',	'QA Engineer (Playwright)',	'qa-engineer-playwright-2',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Drive quality engineering initiatives across customer-facing products and services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead End-to-End (E2E) automation and Customer Journey Testing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Apply AI-enabled Quality Engineering using modern automation technologies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build and maintain modern automation frameworks from the ground up.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Test web applications, APIs, and distributed systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate within Agile/Scrum environments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage test data and environment orchestration.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s or Master\'s degree in Computer Science, Engineering, or related discipline.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years of experience in Software QA and Test Automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong hands-on experience with Playwright and TypeScript.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on manual testing: Functional, Regression, E2E, Integration, Performance, API Testing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience/strong understanding of Salesforce CRM / Service Cloud capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building and maintaining automation frameworks from scratch.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of E2E testing methodologies and customer journey validation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of CI/CD pipelines and DevOps practices.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Git, Azure DevOps, GitHub Actions, Jenkins, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong analytical, debugging, and problem-solving skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent communication and collaboration abilities.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience applying AI and Generative AI to Quality Engineering workflows</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with cloud platforms (AWS, Azure, Google Cloud)</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with performance, accessibility, and security testing</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with test data management and environment orchestration</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-13',	'2026-08-10',	'published',	19,	6,	'2026-07-13 15:23:09',	'2026-08-14 12:59:14',	'2026-08-07 14:58:11'),
(83,	'AC62',	'AC',	62,	'ADSK-9646',	'SAP BPC Developer',	'sap-bpc-developer',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with the Agile Scrum team to design and deliver solution deliverables.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Evaluate business data and information requirements of the globally dispersed transfer pricing setup.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Recommend and drive solution direction and design.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop and support multiple SAP applications as part of a global engineering team.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute as an individual contributor while working collaboratively with cross-functional teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Take ownership of engineering projects and support the company\'s core information technology environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Make effective engineering decisions while ensuring high-quality solution delivery.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree in Engineering, Master\'s in Computer Application, MBA, or related discipline, or equivalent work experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5&ndash;7 years of overall experience with at least 5 years of hands-on experience in SAP BPC.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">SAP ABAP knowledge pertaining to SAP BPC is mandatory.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on experience with SAP Analytics Cloud (SAC), including 3&ndash;4 full lifecycle implementations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in 4&ndash;6 full lifecycle SAP BPC implementation projects.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong verbal and written communication skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to work in different time zones as project demands.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience working with Scrum and Agile processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">SAP BPC Embedded experience combined with SAP ABAP (preferred)</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with SAP SAC.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with SAP PaPM.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Minimum 1 year of SAP SAC or SAP PaPM implementation experience.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-14',	'2026-08-11',	'published',	170,	8,	'2026-07-14 05:01:05',	'2026-08-14 12:58:51',	'2026-07-14 05:01:05'),
(84,	'AC63',	'AC',	63,	'ADSK-9625',	'Technical Program Manager',	'technical-program-manager',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'8 - 14 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"margin-top: 9pt; vertical-align: baseline; text-align: justify;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; color: #4a4a4a; border: 1pt windowtext; padding: 0in;\">We are looking for a seasoned Technical Program Manager to lead pivotal technical initiatives driving end-to-end execution within our Digital Experience Organization. This role demands a strategic thinker with robust experience in program management and a knack for steering cross-functional teams toward success. You will report to the Director of Technical Programs partnering with Product, Engineering, Architecture, Marketing, Analytics and Design.&nbsp;</span><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"color: #4a4a4a; background: white;\">You will be accountable for the delivery of technical programs and initiatives, including planning, execution, risk management, dependency management, and stakeholder alignment. To be successful in this role, you possess a blend of technical expertise, business acumen and a strong capacity to build and develop relationships across different teams and organizational levels.</span></span></p>\r\n<p style=\"margin: 0in; vertical-align: baseline;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; color: #4a4a4a;\">&nbsp;</span><span style=\"font-size: 10pt; font-family: Lato, sans-serif; color: #4a4a4a;\">Our client is looking to hire those who reimagine possible, those with diverse backgrounds who enhance our thinking, and leaders who shape the world and our future. The position is open to those within the Pacific to Central time zones. Preference for those located in the Bay Area, California willing to work hybrid/remote with time in office for critical meetings.</span></p>\r\n<p class=\"MsoNormal\" style=\"background: white; vertical-align: baseline;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; color: #4a4a4a;\">&nbsp;</span><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong><span style=\"color: #4a4a4a;\">Responsibilities:</span></strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Develop and maintain project plans&nbsp;<strong><span style=\"border: none windowtext 1.0pt; mso-border-alt: none windowtext 0in; padding: 0in;\">across multiple technical teams</span></strong>&nbsp;and to provide greater transparency to program status, assignments, dependencies, and outcomes for all program.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with other SMEs to simplify the technically complex, and drive well-educated data-driven decisions across product, engineering, design, and data science representatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Partner in defining the outcomes, deliverables, milestones, and dependencies of the programs.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Drive alignment of cross-organization initiatives through outcome planning, dependency management, and impediment removal.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Identify and communicate project risks and partner with your cross functional team to mitigate conflicts and resolve issues.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Demonstrate excellent judgment, anticipate bottlenecks, lead escalations, make tradeoffs, and balance business needs versus technical constraints.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Support and facilitate roadmap planning and prioritization for each quarter and fiscal year.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Manage day-to-day project activities, meetings, and communication plans to ensure critical project milestones and objectives are met.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Organize, facilitate and execute user acceptance testing (UAT) sessions to ensure optimal success of product releases on time and with quality.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Partner with other TPMs, multiple stakeholders and technology leaders in determining the best technical implementation methods.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Demonstrate excellent judgment, anticipate bottlenecks, lead escalations, make tradeoffs, and balance business needs versus technical constraints.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Plan and ensure delivery by engaging with engineering leadership and teams to build and track clear delivery plans</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Update and communicate program progress across organizational boundaries and levels from individual contributors to senior executive</span></li>\r\n</ul>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"vertical-align: top;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong><span style=\"color: #494949;\">Additional Job Description</span></strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Scheduling of connection points and driving necessary decisions and discussions for cross team collaboration within and outside of your organization, cross technical teams and partners such as Finance, Legal and Marketing with global teams across time zones.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Create visibility of multiple projects across multiple sprints and or quarters</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Facilitate roadmap prioritization across different projects with impact to partner teams</span></li>\r\n</ul>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"vertical-align: baseline;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong><span style=\"color: #4a4a4a;\">Ideal Candidate</span></strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Will possess solid technical expertise, and the ability to impart a sense of urgency and influence their leaders and peers.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Is proactive in stakeholder management and establishing relationship with customers.</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Enjoys operating as \'equal partners\' with Engineering Leaders, Architects, Product Managers, Experience Designers and Product Managers</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #4a4a4a; background: white; vertical-align: baseline; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Is responsive, flexible and able to succeed within a fast changing, timeline driven, agile environment.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Bachelor&rsquo;s degree in an Engineering discipline, Computer Science, Business or a related field</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">8+ years of experience as a Technical Program Manager, Technical Product Manager, or Product Manager</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Extensive experience working with business and technical on highly complex initiatives involving multiple software engineering teams, in a fast-paced environment, using Agile methodologies</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Good technical background and aptitude, detailed driven and have excellent problem-solving abilities</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Ability to communicate effectively with a broad audience</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Zeal for process and operational excellence</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Ability to leverage technical tools to scale programs and solutions</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Experience with Confluence, Asana, Jira, MURL, Lucidchart preferred</span></li>\r\n<li class=\"MsoNormal\" style=\"color: #494949; vertical-align: middle; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif; background: white;\">Desire to continue to learn and challenge yourself</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-14',	'2026-08-11',	'closed',	150,	13,	'2026-07-14 08:17:24',	'2026-07-21 23:52:46',	'2026-07-14 08:17:24'),
(85,	'AC64',	'AC',	64,	'ADSK-9688',	'Technical PM - AEC Product Support',	'technical-pm-aec-product-support',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'8 - 15 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>About the Role</strong></span></p>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are looking for a Technical Program Manager to support a customer-facing design automation software product used by AEC enterprise clients. You will serve as the operational hub between clients, internal engineering teams, and product stakeholders; triaging incoming client issues, owning the product backlog, and managing cross-team delivery. This is not a development role, but you must be technically credible enough to understand what clients are asking, assess feasibility, and route work to the right team with clarity.</span></p>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>What You\'ll Do</strong></span></p>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Client Issue Triage &amp; Routing</strong></span></p>\r\n<ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\">\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Receive and review incoming client tickets; understand the technical nature of each issue and route to the appropriate internal engineering team.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Act as the translator between client-facing language and developer-ready problem statements.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain clear communication with clients on status, timelines, and resolution.</span></li>\r\n</ul>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Backlog &amp; Program Management</strong></span></p>\r\n<ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\">\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Own and prioritize the product backlog across multiple tools - balancing client-reported defects, enhancements, and technical health work.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Translate business requirements and client feedback into build-ready user stories with clear acceptance criteria.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage cross-team dependencies, release cadence, and integration milestones; proactively surface and unblock risks.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Define and track delivery KPIs (cycle time, backlog age, defect resolution latency) and drive continuous improvement.</span></li>\r\n</ul>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Stakeholder Coordination</strong></span></p>\r\n<ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\">\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Run a structured decision-intake process &mdash; batch stakeholder decisions, secure approvals, and maintain a decision log.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Interface with internal software dev teams daily; occasional client-side touchpoints.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Streamline meeting cadence and communication to protect developer focus time.</span></li>\r\n</ul>',	'<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>What You\'ll Bring</strong></span></p>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Required</strong></span></p>\r\n<ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\">\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proven experience as a TPM, Technical PM, or Product Owner in a software/SaaS environment with multiple stakeholders and interconnected systems.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong written and verbal communication, able to interface confidently with enterprise clients and technical teams alike.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on experience with backlog and issue-tracking tools (Jira, Azure DevOps, Airtable, or equivalent) and Agile delivery practices.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with Revit API, Revit add-in/plugin development concepts, and multi-version Revit support realities (credibility-level, not development).</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Working understanding of the C#/.NET ecosystem, enough to follow developer conversations on build, packaging, and release.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">AEC or BIM domain knowledge, understanding of how design and construction teams use software tools in their workflows.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Self-directed and comfortable working autonomously in a remote, distributed contract environment.</span></li>\r\n</ul>\r\n<p class=\"font-claude-response-body break-words whitespace-normal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Nice to Have</strong></span></p>\r\n<ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\">\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with Autodesk Platform Services (APS/Forge), Autodesk Construction Cloud (ACC), or similar AEC cloud platforms.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with data center physical infrastructure, cabling design, or related specialized engineering domains.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Python scripting familiarity.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with cross-tool data contracts, JSON/CSV parameter mapping, or schema versioning across integrated applications.</span></li>\r\n<li class=\"font-claude-response-body whitespace-normal break-words pl-2\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Awareness of telemetry/logging or usage analytics approaches for measuring tool adoption.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-07-16',	'2026-08-13',	'published',	241,	13,	'2026-07-15 19:06:44',	'2026-08-14 12:58:55',	'2026-07-15 19:06:44'),
(86,	'AC65',	'AC',	65,	'ADSK-7777',	'Sr. Red Team Engineer',	'sr-red-team-engineer',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Plan and execute hands-on Red Team operations across enterprise, cloud, identity, endpoint, network, product, AI/LLMs, and infrastructure environments through controlled threat actor emulation and security control validation. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design adversary emulation scenarios using threat intelligence that reflect relevant threat actors, TTPs, attack paths, and business-impacting objectives. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support the development of Red Team methodologies, rules of engagement, tooling standards, reporting formats, metrics, and operational processes. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support external penetration testing vendors to define scope, provide technical guidance, review results, and validate identified security findings.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with Threat Intelligence, Detection Engineering, Threat Hunting, SIRT, Security Engineering, Cloud Security, Application Security, Infrastructure, and AI Security teams. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Assess newly disclosed vulnerabilities and validate exploitability through controlled testing while supporting detection and response improvements. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Participate in purple team exercises to validate telemetry, detections, response procedures, and security control effectiveness. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Perform threat-informed Red Team assessments during merger and acquisition due diligence and onboarding activities. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with Application Security teams to validate exploitable weaknesses and support remediation. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Produce high-quality Red Team reports, executive summaries, technical findings, and remediation guidance. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and implement phishing and vishing campaigns for controlled social engineering testing. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Continuously improve offensive security tools, methodologies, testing standards, and operational processes. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Mentor junior team members through technical coaching and operational guidance.&nbsp;</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Demonstrated experience building, scaling, and operating a Red Team, penetration testing, or offensive security program from inception through maturity.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven hands-on experience safely compromising enterprise environments through controlled offensive security operations designed to emulate real-world adversaries.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven experience designing, building, and leading adversary emulation capabilities, including development of realistic attack scenarios, threat-informed testing&nbsp;Methodologies, purple team exercises, detection validation programs, and control effectiveness assessments aligned to frameworks such as MITRE ATT&amp;CK.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of adversary tactics, techniques, and procedures and their application within offensive security assessments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Advanced knowledge of cloud platforms, including AWS and Azure, from both offensive and defensive perspectives.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of enterprise networking, operating systems, security architectures, and common attack paths.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience measuring Red Team effectiveness through metrics, reporting, and continuous improvement initiatives.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Practical experience using AI within Red Team workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">BA/BS in computer science, information security, or a related field or equivalent experience.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Relevant certifications such as OSCP, OSEP, OSWE, CRTO, CRTM, GXPN, GPEN, CISSP, or equivalent offensive security certifications are an added plus.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-16',	'2026-08-13',	'published',	698,	8,	'2026-07-16 10:18:52',	'2026-08-14 11:56:23',	'2026-07-16 10:18:52'),
(87,	'AC66',	'AC',	66,	'ADSK-9518',	'Senior UX Researcher',	'senior-ux-researcher',	'United States',	'',	'',	'',	'Remote',	'',	'EST',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">We\'re looking for a Senior UX Researcher to help shape an industry-defining Foundation Model for AEC (architecture, engineering, and construction). You\'ll work at the intersection of ML systems and human-centered design &mdash; evaluating model behavior against real user experience, building the measurement infrastructure to do that rigorously, and ensuring insights travel across the teams that need them.<br><br>This is a high-autonomy role spanning multiple initiatives at once. You\'ll need to navigate organizational complexity, stay current on evolving AI products, and synthesize research threads into coherent product direction.<br><br></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Technical tools/applications - Miro, Analysis software&nbsp;<em>like</em>​ Dovetail, Survey software&nbsp;<em>like</em>​ Qualtrics, Analytics software, Microsoft Office</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Experience studying AI tools or helping develop AI Models, demonstrated history of evaluating live products and building methodology systems for live products, experience with complex industries like AEC.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><strong>What you\'ll do<br></strong><br><strong>Research execution</strong></span></p>\r\n<ul style=\"margin-top: 0in; text-align: justify;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Design, conduct, and analyze qualitative and quantitative studies across the full product lifecycle, with a strong emphasis on post-release validation of high-fidelity features.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Apply the right method to the problem: contextual inquiry, usability studies, surveys, participatory design workshops, analytics, and customer advisory councils.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>AI and model evaluation</strong></span></p>\r\n<ul style=\"margin-top: 0in; text-align: justify;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Evaluate AI model outputs and behavior against user experience goals, working fluidly at the ML&ndash;UX boundary.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Build, own, and iterate on measurement protocols for both live and in-flight features.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Collaboration and communication</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Deliver insights to designers, engineers, product managers, and ML researchers &mdash; adapting depth and framing for each audience, up to senior leadership.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Lead design thinking and visioning workshops to turn customer findings into product direction.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Evangelize research broadly: presentations, internal posts, workshops, and other formats that build empathy at scale.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; text-align: justify; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">5+ years of user research embedded in a product or design organization, with a track record leading cross-functional research projects.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; text-align: justify; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Comfort managing multiple research workstreams simultaneously and identifying connections across them.</span></li>\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; text-align: justify; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Experience working across time zones with distributed teams.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Domain knowledge</strong></span></p>\r\n<ul style=\"margin-top: 0in; text-align: justify;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Familiarity with AEC workflows, or hands-on experience with tools like AutoCAD or Revit. Direct industry background in architecture, engineering, construction, or transportation is a strong plus.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>AI fluency</strong></span></p>\r\n<ul style=\"margin-top: 0in; text-align: justify;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Practical experience with AI/ML products &mdash; evaluating model behavior, understanding failure modes, and connecting model performance to user outcomes.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Measurement</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; text-align: justify; font-size: 10pt;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Deep experience designing measurement frameworks and evaluating features against defined success criteria both before and after release.</span></li>\r\n</ul>\r\n<p style=\"margin-bottom: 0in; line-height: normal; font-family: Lato, sans-serif; text-align: justify;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><strong>Education:</strong> Master\'s or PhD in Cognitive or Experimental Psychology, HCI, Human Factors, or a related field preferred</span></p>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-07-17',	'2026-08-14',	'closed',	221,	13,	'2026-07-17 06:46:54',	'2026-07-21 23:51:55',	'2026-07-17 06:46:54'),
(88,	'AC67',	'AC',	67,	'ADSK-9650',	'Release Program Manager',	'release-program-manager',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'8 - 12 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<div><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are seeking a proactive and detail-oriented Program / Release Manager with 5-7 years of experience in managing software releases, coordinating cross-functional programs, and ensuring timely delivery of high-quality products. The ideal candidate will have experience working in Agile environments, collaborating with Engineering, Product, and business stakeholders to plan, coordinate, and execute releases while minimizing risks and ensuring operational excellence.</span></div>\r\n<div>&nbsp;</div>\r\n<div><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Key Roles &amp; Responsibilities</strong></span></div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Plan, coordinate, and manage end-to-end release activities across multiple products and teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collaborate with Engineering and Operations teams to ensure release readiness.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drive cutover planning, execution, and tracking to ensure project milestones are met.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Monitor project progress, identify dependencies, risks, and blockers, and proactively drive mitigation plans.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure compliance with organizational release governance, change management, and deployment processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Coordinate User Acceptance Testing (UAT), production deployments, and post-release validation activities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Prepare and communicate release notes, deployment status, and executive-level progress reports.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work closely with stakeholders to prioritize features, manage scope changes, and align release expectations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Facilitate cross-functional communication and resolve conflicts to ensure seamless collaboration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drive process improvements by identifying opportunities to automate and streamline release and program management activities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Serve as the primary escalation point during release execution, ensuring timely resolution of blocking issues for deployments.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Establish release-related metrics for success, including measures such as release success rates, deployment frequency, refresh cycle time, and change failure rates.</span></li>\r\n</ul>\r\n<p>&nbsp;</p>',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on experience with project management tools such as Microsoft Project and Airtable.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of Software Development Life Cycle (SDLC) and Agile methodologies (Scrum/Kanban).</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with release management processes and CI/CD concepts.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Knowledge of change management and production support processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience working with cloud platforms is desirable.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent communication and time management skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong leadership and stakeholder management abilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to manage multiple priorities in a fast-paced environment.</span></li>\r\n</ul>\r\n<div><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Qualifications</strong></span></div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree in computer science, Information Technology, Engineering, or a related field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5-7 years of experience in Program Management, Release Management, Project Management, or related roles.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">PMP, PMI-ACP, Certified Scrum Master (CSM), SAFe, or ITIL certifications are preferred.</span></li>\r\n</ul>\r\n<div><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Experience</strong></span></div>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience managing enterprise software or SaaS product releases.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience coordinating distributed or global teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Exposure to DevOps practices, CI/CD pipelines, and cloud-based deployments.</span></li>\r\n</ul>\r\n<p>&nbsp;</p>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-07-18',	'2026-08-15',	'closed',	269,	5,	'2026-07-17 19:54:37',	'2026-08-06 22:14:04',	'2026-07-17 19:54:37'),
(89,	'AC68',	'AC',	68,	'ADSK-9100',	'Full Stack Developer',	'full-stack-developer',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'7 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Member of a self-organized agile team building, owning, and operating Identity WebSDK capabilities and related cloud services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, develop, test, and maintain reusable JavaScript/TypeScript SDK capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build reliable, maintainable, type-safe frontend libraries and browser-based integrations across modern browsers.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design clean TypeScript interfaces, reusable abstractions, and developer-friendly APIs for multiple product teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to SDK architecture, implementation, testing, release quality, and long-term maintainability.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with backend Identity service teams on API, authentication flows, session behavior, error handling, and integration requirements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with product teams to support WebSDK adoption, troubleshoot integration issues, gather feedback, and improve developer experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to cloud service development including frontend, backend integration, DevOps, quality, monitoring, alerting, metrics, logging, and troubleshooting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Translate requirements into scalable technical solutions with senior engineers, architects, and product owners.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Identify continuous improvement opportunities in scalability, reliability, usability, security, and maintainability.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Participate in technical design reviews, code reviews, and architecture discussions.Help improve engineering practices, testing strategy, release quality, and team productivity.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree or equivalent in Computer Science or related technical field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7&ndash;10 years overall experience; 6+ years relevant software engineering with strong frontend development.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Deep understanding of JavaScript, TypeScript, HTML, CSS, and modern browser fundamentals.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building scalable, maintainable, reusable frontend code for complex web applications, shared libraries, or platform capabilities.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong TypeScript experience: type definitions, interfaces, generics, reusable abstractions, type-safe API design.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing reusable frontend abstractions and maintainable APIs across multiple teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of modern web standards, browser behavior, and cross-browser compatibility.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with modern frontend frameworks: React, Angular, Vue, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with frontend dev tools: Webpack, Babel, Vite, NPM, Yarn, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with TypeScript build tooling and type declarations for reusable frontend code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Frontend testing experience: unit, integration, and automation testing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with CI/CD practices (Jenkins a plus).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent analytical, troubleshooting, and debugging skills across complex multi-component systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid understanding of software design principles, architectural patterns, and maintainable/reusable code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building high-reliability, high-performance, scalable applications/libraries/services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven ability to write clean, maintainable, reusable, well-tested code.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong collaboration and communication skills across engineers, architects, product owners, operations, support, and product teams.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building reusable JS/TS libraries, SDKs, shared platform capabilities, or developer-facing tools used by multiple teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with IAM concepts: authentication, authorization, user sessions, entitlements, SSO, MFA, user profile management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with identity standards: OAuth 2.0, OpenID Connect, JWT, PKCE, token refresh, session lifecycle management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with browser security: CORS, CSP, SameSite cookies, CSRF, XSS mitigation, secure token handling, redirect security, browser privacy constraints.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing developer-friendly APIs, reusable abstractions, migration paths, and backward-compatible interfaces.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building TypeScript packages with strong type declarations, clean module boundaries, and modern JS build targets.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">SDK/library release practices: semantic versioning, changelog generation, automated releases, package distribution.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience creating/maintaining developer documentation, sample apps, integration/troubleshooting/migration guides.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience supporting adoption of shared platform capabilities across multiple product teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building privacy-conscious telemetry, diagnostics, logging, or observability for client-side libraries/SDKs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience leveraging or contributing to open-source projects.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-19',	'2026-08-16',	'closed',	2,	6,	'2026-07-19 06:48:12',	'2026-07-20 06:20:52',	'2026-07-19 06:48:12'),
(90,	'AC70',	'AC',	70,	'ADSK-9653',	'Backend Focused Python - React Developer',	'backend-focused-python-react-developer',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build responsive, accessible, role-based UIs for a people transformation platform covering approvals, change control, workstream tracking, reporting, and administration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Own frontend implementation using React and TypeScript, ensuring usability and accessibility for internal customers.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop backend APIs, relational data models, workflow services, scenario/version management, and employee-level transaction logic using Python/FastAPI, Java/Spring, Node.js, .NET, or equivalent.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Implement a parallel workflow model supporting soft/hard dependencies, critical-path blockers, refresh requirements, approval invalidation, and stage-gate enforcement.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build approval routing, final-lock controls, immutable audit events, reconciliation logic, dashboards, CSV/EIB-ready exports, and API-ready integration interfaces.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with a co-engineer and Solution Architect to align implementation with security, scalability, data protection, observability, and architectural standards.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with PISD and cross-functional partners to clarify requirements and deliver compliant, privacy-conscious solutions.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Represent engineering in product reviews and roadmap discussions, advocating for production readiness and scalable patterns.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5&ndash;7 years of software engineering experience with ownership of complex production applications.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong experience with React and TypeScript.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong backend experience with Python/FastAPI, Java/Spring, Node.js, .NET, or equivalent enterprise stack.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience designing relational data models, REST APIs, event-driven services, workflow engines, and versioned business objects.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Demonstrated experience with RBAC, approval workflows, audit logging, and secure handling of sensitive data.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of automated testing, CI/CD, cloud deployment, logging, monitoring, and application support.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to translate ambiguous business processes into clear system behaviour.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in multi-team concurrent development environments where changes may invalidate prior approvals or downstream outputs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Track record of collaborating with architects, product owners, and cross-functional stakeholders to deliver production-ready internal tools.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Haves:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with enterprise HR, finance, or workforce planning integrations (e.g., Workday HCM, Workday Adaptive Planning).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with organizational modeling, scenario comparison, hierarchy/tree visualization, drag-and-drop structural design, or workforce analytics.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with graph data models, temporal/versioned data, rules engines, or BPM/workflow platforms.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building internal enterprise products for global, multi-country users.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with relevant products, platforms, or customer domains.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-20',	'2026-08-17',	'closed',	59,	8,	'2026-07-20 06:20:36',	'2026-07-22 06:43:45',	'2026-07-20 06:20:36'),
(91,	'AC71',	'AC',	71,	'ADSK-9649',	'SharePoint Online Developer (M365 / SPFx)',	'sharepoint-online-developer-m365-spfx',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'3 - 5 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, develop, and maintain SharePoint Online solutions, including sites, lists, libraries, and client-side customizations. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build and support SharePoint Framework (SPFx) web parts and extensions while following coding standards and best practices. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate Microsoft 365 services, including Teams, Power Platform, and Microsoft Graph, to deliver scalable collaboration solutions. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Troubleshoot technical issues, deliver high-quality, maintainable solutions, and optimize usability, performance, and scalability. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with team members, management, and internal stakeholders to deliver business requirements and refine solutions through customer feedback. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proactively identify technical challenges, recommend solutions, and contribute to continuous improvement in SharePoint and Microsoft 365 technologies.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">3&ndash;5 years of overall experience with 1&ndash;3 years of relevant experience in SharePoint Online Microsoft solutions. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong experience with SharePoint Online, PnP PowerShell, SharePoint Framework (SPFx), and JavaScript/TypeScript. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Practical experience with SharePoint Online (sites, lists, libraries, permissions, SharePoint Admin Portal) and automation tools such as Power Automate and Azure Runbooks.&nbsp;</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proficiency in PowerShell scripting, including PnP PowerShell and SharePoint Online Management Shell. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with JavaScript or TypeScript, HTML, CSS, and foundational knowledge of SharePoint Framework (SPFx). </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong analytical and problem-solving skills with the ability to follow development processes, standards, and best practices. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Microsoft 365 services, integration techniques, REST APIs, and Microsoft Graph. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree in Computer Science or a related field, or equivalent practical experience.&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Microsoft Graph, Power Automate, and Microsoft 365 integrations. </span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with AirTable is an advantage.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-20',	'2026-08-17',	'published',	412,	8,	'2026-07-20 07:41:51',	'2026-08-15 00:16:22',	'2026-07-20 07:41:51'),
(92,	'AC72',	'AC',	72,	'ADSK-9670',	'AI Software Engineer (LLM & Automation)',	'ai-software-engineer-llm-automation',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and build AI-powered tools to improve software engineering and operational workflows across multiple product teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with technical leads and engineers to understand priorities, codebases, architecture, deployment, and engineering toil sources.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Translate needs into practical AI solutions adopted by teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work hands-on in applied AI domains: developer productivity, workflow automation, retrieval and knowledge systems, agentic workflows, intelligent engineering tools.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ensure systems are evaluated, observable, reliable, and secure for daily engineering use.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Communicate effectively to gather requirements, explain trade-offs, negotiate scope, and document decisions.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5-7 years of experience overall, 3+ years relevant.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong software engineering experience in production apps, developer tools, automation, internal platforms, or data-intensive services.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proficiency in Python, TypeScript, Java, or similar.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience delivering LLM-powered applications.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with retrieval-augmented generation, agentic AI workflows, AI developer/operational tools, workflow automation, AI evaluation/monitoring.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integration experience with Git, CI/CD, issue trackers, documentation, logging, feature flags, messaging.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of APIs, testing, debugging, observability, authentication, error handling, secure delivery.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to learn unfamiliar systems by reading code and collaborating.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience managing ambiguous problems through design, implementation, validation, rollout, adoption.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong communication skills for technical collaboration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Ability to work independently and manage multiple priorities.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with agent frameworks (LangGraph, OpenAI Agents SDK, LangChain).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge systems (semantic/hybrid retrieval, embeddings, sources like Git, Confluence, Jira).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Code intelligence/search (source-code indexing, dependency graphs, OpenSearch, Elasticsearch).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Agentic system design (planning, tool use, memory, retries, human approval).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Developer tooling and coding agents (Claude Code, Cursor, GitHub Copilot).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Tool integration and automation (function calling, APIs, event-driven workflows).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Evaluation and observability (synthetic evaluations, regression testing, LLM-as-judge, LangSmith, OpenTelemetry).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with AI models and security (Anthropic, OpenAI, Amazon Bedrock, guardrails, secure data handling).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Systems and infrastructure (deployment using containers, APIs, workflow engines).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven track record shipping AI tools impacting productivity, quality, reliability, cost, or operations.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-22',	'2026-08-19',	'published',	396,	8,	'2026-07-22 04:21:40',	'2026-08-15 00:15:05',	'2026-07-22 04:21:40'),
(93,	'AC73',	'AC',	73,	'ADSK-9699',	'Source-to-Pay (S2P) Business Analyst',	'source-to-pay-s2p-business-analyst',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'7 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support end-to-end Source to Pay (S2P) transformation including sourcing, purchasing, invoicing, and payments ensuring accuracy and completeness.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Drive implementation and process improvements through stakeholder partnership for future-state process definition, requirements gathering, design, testing, deployment, and automation identification.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Analyze spend, invoice, and payment data to identify trends, risks, and opportunities for better visibility and decision-making.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with Procurement, Accounts Payable, FP&amp;A, Treasury, and technology teams to align processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support data governance, compliance, audit readiness, user training, change adoption, QA, and UAT.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work with business users, engineers, system integrators, and vendors to resolve issues and support project milestones.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Focus on requirements gathering, design discussions, UAT, process transformation, and system enhancements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong expertise in SAP S/4HANA mandatory.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on experience with at least one procurement platform: Coupa (preferred), Ariba, Zip, or Level Path (good to have).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of S2P lifecycle including procurement, accounts payable, payments, and vendor management.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor&rsquo;s degree in Finance, Accounting, Supply Chain, or related field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7&ndash;10 years of relevant experience in Business/System Analysis within S2P, P2P, Accounts Payable, Procurement, or Finance Operations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">SAP S/4HANA expertise.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong analytical, communication, and problem-solving skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in procurement transformation and implementation.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Coupa, Ariba, Zip, or Levelpath.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Power BI, Excel, Alteryx, and AI-enabled tools.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Consulting background.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with RPA and AI/ML automation initiatives.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-22',	'2026-08-19',	'published',	609,	8,	'2026-07-22 06:34:17',	'2026-08-15 00:13:22',	'2026-07-22 06:34:17'),
(94,	'AC74',	'AC',	74,	'ADSK-9693',	'Engineering Drawing SME (CAD & GD&T)',	'engineering-drawing-sme-cad-gdt',	'India',	'Maharashtra',	'Pune',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'10 - 13 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Serve as Engineering Drawing Subject Matter Expert, linking engineering practices with product development.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with Product Management, UX Design, Engineering, Customer Success, and strategic customers to influence roadmap and features.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provide expertise in creation, interpretation, and review of engineering drawings throughout product lifecycle.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Guide understanding of drawing production across industries: consumer products, industrial machinery, tooling, sheet metal, machined components, weldments, furniture, electronics, complex assemblies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Advise on international and regional drawing standards (ASME Y14.x, ISO, DIN, JIS).</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Represent downstream drawing consumers: manufacturing, machining, fabrication, assembly, quality inspection, procurement, suppliers, service.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Validate designs and features via reviews, prototypes, and customer engagements.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Create workflows, best practices, demos, and educational materials.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Contribute to defining, developing, and validating functional specs for new drawing features in Fusion.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">10+ Years industry experience creating and reviewing engineering drawings in manufacturing.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of engineering drawing lifecycle from concept to production support.Deep knowledge of drawing standards and practices including GDCT, ASME, ISO, DIN, JIS.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience across multiple manufacturing domains: consumer products, industrial machinery, tooling, sheet metal, machined components, weldments, complex assemblies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on experience with professional CAD systems for production drawings.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with PLM, PDM, or ERP systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Background in design reviews, supplier collaboration, or manufacturing engineering.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience creating workflows, best practices, product demonstrations, and technical documentation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to defining functional specifications and supporting product roadmap initiatives for engineering drawing solutions.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-24',	'2026-08-21',	'published',	408,	8,	'2026-07-24 10:37:01',	'2026-08-15 00:14:30',	'2026-07-24 10:37:01'),
(95,	'AC75',	'AC',	75,	'ADSK-9640',	'Sr. Mechanical Design & QA Engineer',	'sr-mechanical-design-qa-engineer',	'United States',	'Michigan',	'Novi',	'',	'Hybrid',	'',	'EST',	'W2 Contract',	'',	'10 - 15+ years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are seeking an experienced <strong>Senior Mechanical Design Checker</strong> to review and validate 2D mechanical engineering drawings before they are released for manufacturing. In addition to drawing review, you will collaborate with a software development team to help improve AI-powered drawing validation tools by providing engineering expertise, testing, and documentation.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">This role is ideal for someone with a strong background in industrial machine design who enjoys combining engineering knowledge with emerging AI technology.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>&nbsp;</strong><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Review and redline approximately <strong>40&ndash;50 mechanical drawings per week</strong> for:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Accuracy</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manufacturability</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">GD&amp;T compliance</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drafting standards</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Dimensioning best practices</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure drawings meet applicable engineering and manufacturing standards.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work closely with software developers to improve AI-based drawing checking tools.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Create and validate engineering datasets used to train and test AI models.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop and document engineering rules and dimensioning rationale.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Validate AI-generated results using professional engineering judgment.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Extensive experience creating <strong>and</strong> checking 2D mechanical drawings.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong practical knowledge of <strong>GD&amp;T</strong>, including formal training or certification.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience applying drafting standards such as:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">ANSI/ASME Y14.5</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">ISO standards</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Other industry drafting standards</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proficiency with both <strong>imperial and metric</strong> drawings.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong experience with <strong>AutoCAD 2D</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with at least one 3D CAD platform such as <strong>Autodesk Inventor</strong>, <strong>SolidWorks</strong>, or <strong>Mechanical Desktop</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of dimensioning methods including baseline, chain, ordinate, mixed-mode, and tabular dimensioning.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience reviewing manufacturability of:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Machined parts</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sheet metal</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Weldments</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Castings</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Forgings</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Background designing or documenting <strong>industrial machinery with moving mechanical systems</strong>.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Industry Experience</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Candidates from the following industries are highly preferred:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Custom or special-purpose machinery</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Industrial automation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Material handling and conveyor systems</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Machine tools and CNC equipment</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Robotics and end-of-arm tooling</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Aerospace tooling</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Pneumatic and hydraulic equipment</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience collaborating with software development teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Understanding of AI-assisted engineering workflows.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with CAD automation, scripting, or macros (such as AutoLISP).</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to clearly explain engineering decisions and technical reasoning.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>What We\'re Looking For</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong attention to detail.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent communication skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to explain the reasoning behind engineering and dimensioning decisions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Comfortable working in a collaborative, fast-paced environment with engineering and software teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Open to iterative development and continuous improvement.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-27',	'2026-08-24',	'published',	99,	13,	'2026-07-27 18:06:48',	'2026-08-14 22:35:37',	'2026-07-27 18:06:48'),
(96,	'AC76',	'AC',	76,	'BLCK-0260',	'Supplier Onboarding Lead',	'supplier-onboarding-lead',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Our client is seeking an experienced <strong>Supplier Onboarding Lead</strong> to oversee and optimize the global supplier onboarding program. This role is responsible for leading supplier onboarding operations, ensuring supplier compliance, maintaining supplier master data integrity, and driving operational excellence across global procurement functions.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">The ideal candidate will have a strong background in supplier onboarding, procurement operations, accounts payable, or shared services, along with experience leading teams, driving process improvements, and partnering cross-functionally with Procurement, Finance, Legal, Compliance, Tax, Treasury, and Risk organizations.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Key Responsibilities</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Supplier Onboarding Operations</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Lead the day-to-day operations of the global supplier onboarding program, ensuring timely, accurate, and compliant onboarding across multiple regions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Oversee supplier onboarding, supplier master record maintenance, payment enablement, and supplier lifecycle management activities.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure operational processes meet defined SLAs while delivering an excellent supplier and stakeholder experience.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Act as the primary escalation point for complex supplier onboarding issues requiring cross-functional collaboration.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Monitor team capacity, workload, and operational performance to ensure consistent service delivery.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Supplier Due Diligence &amp; Compliance</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Oversee supplier due diligence activities, including tax documentation, sanctions screening, supplier verification, payment setup, and compliance reviews.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with Legal, Compliance, Tax, Treasury, Security, and Third-Party Risk Management (TPRM) teams to ensure compliance with company policies and regulatory requirements.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain complete, accurate, and audit-ready supplier documentation.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Identify operational risks, control gaps, and process exceptions while implementing corrective actions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support internal and external audits by maintaining strong operational controls and documentation.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Supplier Master Data &amp; Payment Enablement</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage supplier master data governance and ensure supplier information remains accurate and compliant.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Oversee supplier payment setup, including banking verification, payment method configuration, and tax documentation validation.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain controls governing supplier record changes and payment information updates.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collaborate with Accounts Payable and Treasury to improve supplier payment readiness while minimizing operational and fraud risks.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Drive initiatives to improve onboarding cycle times and first-time quality.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Process Improvement &amp; Operational Excellence</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Continuously evaluate supplier onboarding processes and identify automation and efficiency opportunities.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with Procurement Technology and IT teams to implement workflow enhancements and system improvements.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop dashboards and reports measuring onboarding volume, cycle time, SLA performance, quality, and compliance.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Lead root cause analysis and implement sustainable operational improvements.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support procurement transformation initiatives by scaling standardized onboarding processes globally.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Team Leadership</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Lead, coach, and develop a high-performing supplier onboarding team.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop and maintain Standard Operating Procedures (SOPs), training materials, and operational documentation.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Establish performance metrics and quality standards aligned with Procurement Operations objectives.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Foster strong partnerships across Procurement, Finance, Accounts Payable, Legal, Compliance, Tax, Treasury, and business teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Promote a culture of accountability, continuous improvement, and operational excellence.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5+ years of experience in <strong>Supplier Onboarding, Procurement Operations, Accounts Payable, Shared Services, or Supplier Management</strong> within a global organization.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">1+ years of experience leading or supervising operational teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong knowledge of supplier onboarding processes, supplier master data, tax documentation, payment setup, and Procure-to-Pay (P2P) operations.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience working cross-functionally with Procurement, Finance, Accounts Payable, Tax, Treasury, Legal, Compliance, Security, and Risk organizations.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience managing operational performance through KPIs, SLAs, quality metrics, and continuous improvement initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of supplier data governance, operational controls, audit requirements, and compliance.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience leading process improvement and technology-driven transformation initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proficiency with procurement orchestration platforms, ERP systems, supplier onboarding platforms, and workflow automation tools.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent communication, stakeholder management, analytical, and problem-solving skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proven ability to influence stakeholders, lead through ambiguity, and build scalable operational processes.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree in Business Administration, Finance, Accounting, Supply Chain, Procurement, or a related field preferred (not required).</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-27',	'2026-08-24',	'published',	234,	13,	'2026-07-27 18:13:05',	'2026-08-14 22:36:33',	'2026-07-27 18:13:05'),
(97,	'AC77',	'AC',	77,	'ADSK-9679',	'Workday Adaptive Planning Consultant',	'workday-adaptive-planning-consultant-2',	'Canada',	'',	'',	'',	'Remote',	'',	'Any',	'T4 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'USD',	'Per Hour',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">We are seeking an experienced <strong>Workday Adaptive Planning Consultant</strong> with strong expertise in <strong>Workforce Planning (WFP)</strong> and <strong>Headcount Planning</strong> to support enterprise planning initiatives. The ideal candidate will have hands-on experience designing and implementing Adaptive Planning models, partnering with FP&amp;A and HR stakeholders, and delivering scalable workforce planning solutions with minimal supervision.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, build, and enhance <strong>Workday Adaptive Planning</strong> workforce and headcount planning models.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with FP&amp;A, HR Operations, and business stakeholders to gather requirements and deliver planning solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Lead or support Workday Adaptive Planning implementation and enhancement projects.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop workforce planning models using Adaptive Planning best practices.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate Adaptive Planning with enterprise systems such as Workday HCM, Snowflake, Power BI, and other financial applications.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Create process documentation, user guides, and deliver end-user training.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support planning, forecasting, reporting, and continuous process improvements.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate with cross-functional teams to optimize workforce planning and reporting capabilities.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\"><strong>3&ndash;5+ years</strong> of hands-on experience with <strong>Workday Adaptive Planning</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven experience implementing or enhancing <strong>Workday Adaptive Planning</strong> solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong expertise in <strong>Workforce Planning</strong>, <strong>Headcount Planning</strong>, and financial planning models.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience partnering with <strong>FP&amp;A</strong>, <strong>HR Operations</strong>, or <strong>HR Systems</strong> teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience integrating Adaptive Planning with Workday HCM, Snowflake, Power BI, or similar enterprise applications.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent analytical, communication, and stakeholder management skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong experience creating process documentation and delivering user training.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday Adaptive Planning Certification.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in a high-growth SaaS or publicly traded company.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of financial planning, budgeting, forecasting, and workforce management processes.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday Adaptive Planning</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workforce Planning (WFP)</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Headcount Planning</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">FP&amp;A / HR Operations</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Workday HCM</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Financial Planning &amp; Forecasting</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Process Documentation &amp; User Training</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Stakeholder Management</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-28',	'2026-08-25',	'closed',	10,	13,	'2026-07-27 19:34:30',	'2026-07-28 20:58:13',	'2026-07-27 19:34:30'),
(98,	'AC79',	'AC',	79,	'ADSK-9694',	'Sr. C++ Developer (Python, Qt)',	'sr-c-developer-python-qt',	'India',	'Maharashtra',	'Pune',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work in Agile Scrum teams with 2-week sprints and strong test automation focus.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, implement, test, and maintain Fusion 360 features primarily in C++.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Own quality and delivery excellence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Write technical design documents, participate in design/code reviews, and estimate tasks.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Collaborate closely with developers, QA, UX designers, and global teams.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Program using Microsoft Visual Studio on Windows and Xcode on macOS.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Present in global technical discussions and mentor team members.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Adapt flexibly to changing priorities and demonstrate customer success passion.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree in Computer Science, Engineering, Mathematics, or a related field.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years of industry experience, including 4+ years of relevant experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong proficiency in C++, Data Structures, Object-Oriented Programming (OOP), Design Patterns, debugging, and problem-solving.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in graphics, CLI, database, and functional application development.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Qt, Python, JavaScript, and Windows &amp; Mac application development.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience using AI-assisted development tools such as GitHub Copilot, Cursor, or Claude.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong collaboration skills with the ability to quickly learn and work on large software systems.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with 3D/2D CAD software.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of Agile development practices.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with JSON, Jira, and Jenkins.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in API development and test automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of Design &amp; Manufacturing Drawings.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with ObjectARX.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-28',	'2026-08-25',	'published',	240,	8,	'2026-07-28 05:52:54',	'2026-08-15 00:15:06',	'2026-07-28 05:52:54'),
(99,	'AC80',	'AC',	80,	'BLCK-5149',	'Sr. Reconciliation Data Analyst - Payments',	'sr-reconciliation-data-analyst-payments',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"isSelectedEnd\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Our client is seeking a detail-oriented <strong>Reconciliation &amp; Reporting Analyst</strong> to join the Recon &amp; Reporting team. In this role, you will be responsible for reconciling financial transactions across card networks, banks, processors, and internal systems to ensure financial accuracy and reporting integrity. You will investigate discrepancies, automate reporting processes, collaborate with cross-functional teams, and contribute to improving reconciliation processes and controls.</span></p>\r\n<p class=\"isSelectedEnd\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">This is an excellent opportunity for someone with strong analytical skills, SQL expertise, and experience in payments, reconciliation, accounting, or finance operations.</span></p>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Key Responsibilities</span></h2>\r\n<h3><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Financial Reconciliation &amp; Reporting</span></h3>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Perform daily, weekly, and monthly reconciliations between card networks, banking partners, processors, and internal financial systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Investigate and resolve reconciliation breaks by performing detailed root cause analysis.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Design, develop, and maintain automated SQL-based reconciliation reports and dashboards.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Monitor settlement, funding, and banking activities to identify discrepancies and operational issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support month-end close by preparing reconciliation reports and documentation for accounting and audit purposes.</span></li>\r\n</ul>\r\n<h3><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Data Analysis &amp; Process Improvement</span></h3>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Analyze large transactional datasets to identify trends, exceptions, and opportunities for automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop operational KPIs and reporting dashboards to improve reconciliation efficiency.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain process documentation, SOPs, and operational runbooks.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Recommend and implement process improvements to enhance controls and operational efficiency.</span></li>\r\n</ul>\r\n<h3><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-Functional Collaboration</span></h3>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with Engineering, Product, Accounting, Treasury, Compliance, and Finance teams to resolve reconciliation issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Define business requirements for system enhancements and validate production changes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Respond to reconciliation and reporting requests from internal stakeholders and external partners.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Utilize AI tools to improve analytical efficiency and operational insights.</span></li>\r\n</ul>',	'<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree in <strong>Finance, Accounting, Economics, Business, or a quantitative field</strong> (Master\'s degree preferred but not required).</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>5+ years</strong> of experience in reconciliation, payment operations, settlements, accounting, finance analytics, or related fields.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong SQL skills with experience building automated reports and reconciliation queries.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Advanced Microsoft Excel skills, including Pivot Tables, Lookups, and complex formulas.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of financial reconciliations, accounting principles, and money movement.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent analytical, problem-solving, and communication skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to manage recurring deadlines while maintaining exceptional attention to detail.</span></li>\r\n</ul>\r\n<h2><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Preferred Qualifications</span></h2>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with <strong>payment card networks</strong> (Visa, Mastercard, Amex, Discover).</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Knowledge of payment rails including <strong>ACH, Wire, SWIFT, RTP, and FedNow</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with reconciliation platforms, banking portals, and BI tools such as <strong>Looker</strong> or <strong>Tableau</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Exposure to month-end close, settlement reporting, fee reconciliation, regulatory reporting, SOX controls, or audit support.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience improving operational processes through automation and continuous improvement initiatives.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-28',	'2026-08-25',	'published',	603,	13,	'2026-07-28 16:17:10',	'2026-08-14 22:35:55',	'2026-07-28 16:17:10'),
(100,	'AC81',	'AC',	81,	'ADSK-9714',	'Senior VoC Program Manager',	'senior-voc-program-manager',	'India',	'Karnataka',	'Bengaluru',	'',	'Hybrid',	'',	'IST',	'Full-time',	'',	'5 - 7 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Own operational delivery of relationship surveys and customer listening programs, managing workflows including targeting, scheduling, distribution, reminders, and tracking.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Oversee customer interview programs with scheduling, capacity planning, vendor support, and reporting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Manage VoC program KPIs, operational health metrics, and lead continuous improvement initiatives.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Coordinate resolution of operational, data, workflow, and platform issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Maintain governance, compliance, and operational controls.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop and maintain playbooks, training materials, and self-service resources; deliver stakeholder onboarding and enablement.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support closed-loop feedback processes to improve accountability and link feedback to business actions.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Bachelor\'s degree or equivalent experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years of experience in customer feedback programs, research/CX operations, or program management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on experience with Qualtrics, Medallia, and Salesforce workflows.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong program management, operational excellence, analytical, problem-solving, and communication skills.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Proven experience managing cross-functional stakeholders and driving process improvements.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-Have: </strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience in Customer Success, Customer Experience (CX), or Customer Insights.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with enterprise-scale Voice of Customer (VoC) programs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Knowledge of training and enablement programs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with customer research methodologies.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience using analytics platforms.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-07-29',	'2026-08-26',	'published',	275,	8,	'2026-07-29 09:29:51',	'2026-08-15 00:15:30',	'2026-07-29 09:29:51'),
(101,	'AC82',	'AC',	82,	'ADSK-9689',	'Digital Sales Representative',	'digital-sales-representative',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'2 - 6 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Our client is seeking a motivated Digital Sales Representative to generate and qualify new sales opportunities through high-volume customer outreach. This role is ideal for someone with strong prospecting skills, excellent communication abilities, and experience managing a high volume of inbound and outbound leads.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Working closely with Account Executives, Marketing, and Sales Operations, you will engage prospective customers, qualify leads, maintain CRM data, and schedule meetings that help drive pipeline growth and revenue.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Generate and qualify new sales opportunities through 95% inbound and 5% outbound outreach.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Conduct high-volume phone outreach and engage prospective customers via email and CRM tools.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with Account Executives to identify customer needs and schedule qualified meetings.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage lead flow and maintain accurate customer information in Salesforce (SFDC).</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collaborate with Marketing and Sales Operations to prioritize leads and improve pipeline conversion.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Utilize CRM data and reporting insights to optimize outreach strategies.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Consistently achieve activity and pipeline generation goals while delivering an excellent customer experience.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree required.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">2&ndash;3 years of experience in Sales Development, Business Development, Inside Sales, or a similar customer-facing sales role.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proven experience in Sales Development Representative (SDR) or cold-calling environments.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience handling high-volume lead outreach and prospecting activities.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent verbal and written communication skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Comfortable using Salesforce (SFDC) or other CRM platforms.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong organizational skills with the ability to manage multiple leads and priorities.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Self-motivated, goal-oriented, and able to work in a fast-paced sales environment.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience supporting SaaS, technology, or B2B sales organizations.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience collaborating with Account Executives and Marketing teams.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong customer engagement and relationship-building skills.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Top 3 Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sales Development Representative (SDR) and/or cold-calling experience.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent communication skills (phone, email, and CRM/Salesforce).</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience in high-volume lead generation and outreach.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-07-29',	'2026-08-26',	'closed',	78,	13,	'2026-07-29 17:55:50',	'2026-08-06 22:14:25',	'2026-07-29 17:55:50'),
(102,	'AC83',	'AC',	83,	'UKG-5001',	'Ironclad CLM Configuration Consultant',	'ironclad-clm-configuration-consultant',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'6 - 12 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"isSelectedEnd\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are looking for an&nbsp;<strong>Ironclad CLM specialist</strong> with hands-on experience configuring contract workflows, templates, approvals, and related CLM functionality.</span></p>\r\n<h3><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Responsibilities</span></h3>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Configure Ironclad workflows for NDAs, MSAs, Order Forms, amendments, and other contract types.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Build and maintain workflow forms, approval routing, templates, playbooks, and metadata.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Translate business requirements into scalable Ironclad configurations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Configure user roles, permissions, contract fields, and workflow rules.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support requirements gathering, testing/UAT, deployment, and ongoing optimization.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work with Salesforce and business teams to align CLM workflows with existing processes.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Troubleshoot configuration issues and improve workflow efficiency.</span></li>\r\n</ul>',	'<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5+ years of experience in <strong>CLM implementation, SaaS implementation, or technical consulting</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on experience with <strong>Ironclad </strong>specifically.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong experience with workflow, template, approval, and metadata configuration.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience translating business requirements into system configurations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Understanding of contract processes across Sales, Legal, Finance, or Procurement.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong communication and stakeholder management skills.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Important:</strong> This is a <strong>technical CLM configuration role</strong>, not a contract review, legal operations, procurement, or deal desk position.</span></p>',	'<p><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-07-31',	'2026-08-28',	'published',	124,	5,	'2026-07-30 19:05:16',	'2026-08-14 22:35:48',	'2026-07-30 19:05:16'),
(103,	'AC84',	'AC',	84,	'UKG-5002',	'Ironclad Integration Specialist',	'ironclad-integration-specialist',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'6 - 12 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"isSelectedEnd\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are looking for a&nbsp;<strong>technical integration specialist</strong> experienced in connecting Ironclad with Salesforce and other enterprise systems.</span></p>\r\n<h3><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Responsibilities</span></h3>\r\n<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Configure and support <strong>Ironclad&ndash;Salesforce integrations</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Set up workflow launch, workflow sync, and record synchronization.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Map Salesforce objects, fields, IDs, and contract metadata between systems.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Configure Ironclad managed packages, connected applications, authentication, and integration settings.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Troubleshoot synchronization, data mapping, and integration issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work with Salesforce teams on objects, fields, flows, APIs, and data models.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support integrations using platforms such as Workato, MuleSoft, or Zapier.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Monitor data flows and help maintain reliable contract-related integrations.</span></li>\r\n</ul>',	'<ul data-spread=\"false\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5+ years of experience in <strong>Salesforce administration/development, systems integration, or technical consulting</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on experience <strong>integrating Ironclad (CLM platform) with Salesforce</strong>.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of Salesforce objects, fields, flows, APIs, and managed packages.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with data mapping and system-to-system integrations.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with REST APIs, OAuth, authentication, and integration troubleshooting.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with middleware/iPaaS platforms is a plus.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong analytical and problem-solving skills.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Important:</strong> This is a <strong>technical integration role</strong>, not a legal, contract administration, procurement, or deal desk position.</span></p>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-07-31',	'2026-08-28',	'published',	73,	5,	'2026-07-30 19:08:41',	'2026-08-14 22:35:52',	'2026-07-30 19:08:41'),
(104,	'AC85',	'AC',	85,	'ADSK-9702',	'Anaplan Analyst (FP&A)',	'anaplan-analyst-fpa',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We\'re looking for an experienced <strong>Anaplan Senior Analyst</strong> to join a growing <strong>FP&amp;A Solutions</strong> team and help design, build, implement, and maintain enterprise Anaplan solutions that support Finance Transformation initiatives.</span></p>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Role &amp; Responsibilities</strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Design, build, implement, and maintain Anaplan-based solutions in partnership with finance teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Translate business processes into sophisticated multi-dimensional Anaplan models (architecture, data schema, calculation methodologies, reporting)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain existing models; incorporate new functionality, develop enhancements, resolve production issues</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Author technical documentation: model design, deployment procedures, run-state/admin instructions</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Participate in data integration pipeline development between source systems and Anaplan (APIs, data models, architectural elements)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Identify and remediate technical debt to maintain high model health</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Monitor and validate data processing workflows to/from Anaplan</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Build relationships and trust with business model owners, end users, and stakeholders</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Participate in UAT, script writing, and deployment activities</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Provide hands-on training and office hours to drive end-user adoption</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Apply Anaplan model-building best practices per our client and Anaplan Community standards</span></li>\r\n</ul>\r\n<p style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Project Overview</strong></span></p>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Role sits within a growing FP&amp;A Solutions team at our client</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Focus on Finance Transformation &mdash; streamlining and solving complex financial business problems via Anaplan</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-functional collaboration with internal organizations on data integrations and process improvements</span></li>\r\n</ul>',	'<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5+ years of Anaplan Model Building experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Anaplan Certified Model Builder Level 2 or above (required)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong finance acumen &mdash; FP&amp;A, financial planning, forecasting, sales planning</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Revenue planning experience &mdash; ACV, bookings, billings, topline planning</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to speak finance language, influence stakeholders, and advise on process optimization</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience in iterative/agile work practices (Lean, Agile, Anaplan Way)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Technical proficiency in Excel, Anaplan, and/or comparable tools (Adaptive Planning, Pigment, SAP BPC, Planful, TM1, or other cloud solutions)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent quantitative and analytical skills; high attention to detail</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong listening and communication skills; ability to switch between technical and business contexts</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Undergrad degree in finance, accounting, business, or engineering (or equivalent experience)</span></li>\r\n</ul>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><em>Nice-to-Haves / Behavioral Attributes:</em></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Flexibility to work in large teams, small teams, independently, remote, and in-person</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Courage to voice divergent views and drive productive, solution-oriented conversations</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ownership mindset &mdash; takes responsibility for outcomes and leads remediation efforts</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Fosters an inclusive environment where people can bring their authentic selves</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-08-03',	'2026-08-31',	'published',	241,	13,	'2026-08-03 16:57:10',	'2026-08-14 22:14:32',	'2026-08-03 16:57:10'),
(105,	'AC86',	'AC',	86,	'JUUL-0497',	'HR Operations Coordinator',	'hr-operations-coordinator',	'United States',	'',	'',	'',	'Remote',	'',	'EST',	'W2 Contract',	'',	'2 - 6 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Our client is seeking a detail-oriented and proactive <strong>People Operations Coordinator</strong> to support day-to-day HR operations and deliver an exceptional employee experience. This role partners with cross-functional and international teams to manage employee lifecycle processes, maintain HR data integrity, coordinate onboarding and offboarding, and provide administrative support across People Operations.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain the accuracy and integrity of employee records and HR data.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Coordinate employee onboarding, including background checks and Form I-9/E-Verify verification.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Facilitate virtual new hire orientation sessions.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Process employee data changes within HR systems.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Respond to employee inquiries regarding HR policies, procedures, and benefits.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Manage contingent worker requests and tickets in ServiceNow.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Conduct personnel record audits and process employment verification requests.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Administer the employee referral bonus program.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support employee offboarding in compliance with state and federal labor laws.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collaborate with cross-functional and international teams to ensure a seamless employee experience.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Assist with HR projects and process improvement initiatives.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Bachelor\'s degree or equivalent combination of education and relevant work experience.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>2+ years</strong> of corporate experience, preferably in <strong>People Operations, Human Resources, or HR Administration</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience or familiarity with <strong>Workday</strong>, <strong>ServiceNow</strong>, Applicant Tracking Systems (e.g., Greenhouse), and the <strong>I-9/E-Verify</strong> process.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong organizational, communication, and time management skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Comfortable presenting and communicating with employees virtually and in person.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proficiency in <strong>Google Workspace</strong> and <strong>Microsoft Office</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to handle confidential information with professionalism and discretion.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Process improvement mindset with the ability to work in a fast-paced, evolving environment.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience supporting HR operations in a global organization.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with employee onboarding, offboarding, employment verification, and contingent workforce administration.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with HR compliance and employment documentation.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Top 3 Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">HR Operations or People Operations experience.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with <strong>Workday</strong> and <strong>ServiceNow</strong> (strongly preferred).</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Knowledge of <strong>I-9</strong>, <strong>E-Verify</strong>, and employee onboarding processes.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-08-04',	'2026-09-01',	'closed',	1228,	13,	'2026-08-04 16:53:55',	'2026-08-13 14:31:56',	'2026-08-04 16:53:55'),
(106,	'AC87',	'AC',	87,	'ADSK-9723',	'Gainsight Administrator',	'gainsight-administrator',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<div class=\"mb1\">\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Role is focused on helping go-to-market teams extract more value from Gainsight by translating business needs into practical, scalable solutions</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Less focused on enterprise architecture; more focused on direct partnership with business teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Success is measured by adopted workflows, trusted stakeholder relationships, reliable automations/reports, and continuous improvement in how the org uses Gainsight to drive customer health, retention, and growth</span></li>\r\n</ul>\r\n</div>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Role &amp; Responsibilities</strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner directly with go-to-market teams (Customer Success, Sales, Renewals, Support, Marketing, Operations) to translate business needs into Gainsight solutions</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Configure and maintain Gainsight features: playbooks, CTAs, success plans, rules engine, automations, reports, dashboards, and customer health models</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Build and refine workflows to help customer-facing teams prioritize work, manage risk, drive adoption, and improve customer outcomes</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Create and maintain reporting and dashboards for visibility into customer health, team activity, adoption, risk, and operational performance</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support development and optimization of playbooks, lifecycle journeys, customer segmentation, health scores, and automated alerts</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Gather end-user feedback and continuously improve workflows, usability, and adoption</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Troubleshoot issues, investigate data/configuration problems, and provide timely user support</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Document configurations, processes, business logic, and enablement materials</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Partner with data, systems, and operations teams to ensure Gainsight leverages accurate and actionable data</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Stay current on Gainsight product capabilities and recommend workflow improvements</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Explore opportunities to leverage AI, MCP, and related technologies to improve automation, insights, and operational efficiency</span></li>\r\n</ul>',	'<div class=\"mb1\"><strong><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Must-Haves:</span></strong></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">5+ years of hands-on Gainsight admin experience in a go-to-market, Customer Success, RevOps, or Sales Ops environment</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Strong working knowledge of Gainsight configuration: rules, playbooks, CTAs, reporting, dashboards, success plans, and automation workflows</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Ability to engage directly with business stakeholders, understand ambiguous requests, and translate needs into system solutions</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Familiarity with customer success operations</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Proactive stakeholder partnership &mdash; not just ticket-queue support</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Strong problem-solving, diagnostic, and tradeoff evaluation skills</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Experience supporting customer-facing teams (CS, Sales, Renewals, Support, Account Management)</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Comfortable working with data, reports, dashboards, segmentation logic, and operational metrics</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Strong communication skills, including explaining technical concepts to non-technical users</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Detail-oriented, organized, able to manage multiple priorities and stakeholder needs</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Experience documenting processes, configurations, and user guidance</span></li>\r\n</ul>\r\n<div class=\"mb1\"><strong><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Nice-to-Haves:</span></strong></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Gainsight Administrator certification</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Salesforce or other CRM integration experience</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Background in CS Ops, RevOps, GTM Systems, or Business Systems</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Familiarity with AI-enabled workflows, MCP, automation agents, or emerging AI capabilities</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">Experience driving user adoption through training, enablement, or office hours</span></li>\r\n<li style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Understanding of customer lifecycle management, health scoring, risk management, renewals, adoption, and expansion motions.</span></li>\r\n</ul>\r\n<p style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><strong>Key Points:</strong><br></span></p>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Flag Gainsight Admin-level certification, a plus</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ideal profile: consultative, curious, comfortable with ambiguity; digs into the \"why\" behind requests rather than just executing tickets.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong signal: candidates who can configure a playbook, build a dashboard, troubleshoot an automation, AND hold strategic conversations with CS leadership.</span></li>\r\n</ul>\r\n<p style=\"font-size: 10pt; font-family: Lato, sans-serif;\"><span style=\"font-size: 10pt; font-family: Lato, sans-serif;\">&nbsp;</span></p>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-08-07',	'2026-09-04',	'closed',	35,	5,	'2026-08-06 22:04:28',	'2026-08-11 23:09:28',	'2026-08-06 22:04:28'),
(107,	'AC88',	'AC',	88,	'ADSK-9720',	'Sr. Network & Cloud Security Engineer (AWS)',	'sr-network-cloud-security-engineer-aws',	'India',	'',	'',	'',	'Remote',	'',	'IST',	'Full-time',	'',	'7 - 13 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Roll out and manage AWS firewall solutions including AWS Network Firewall, Security Groups, and NACLs.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Troubleshoot and remediate firewall/ACL configuration issues.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Support network design changes such as segmentation, routing, and security zoning within AWS.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build automation (scripts, IaC, tooling) for firewall management and remediation workflows, leveraging AI-assisted approaches.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design, implement, and manage scalable security controls for ZTNA, SASE, IDS, and auditing tools in cloud infrastructures.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Hands-on work with firewalls, switches, routers, VPNs, network traffic security controls, and firewall policy management.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud security tasks involving AWS, Azure, GCP, security groups, WAF, and DDoS protection.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop automation integrating firewalls with device management platforms using Python, Bash, APIs, Terraform, CloudFormation, and user data scripts.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Use network monitoring and analytics tools like NetFlow, sFlow, and packet analysis.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Must-have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong AWS networking/security experience: VPC, Security Groups, NACLs, AWS Network Firewall.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">7-10 years cybersecurity/security engineering experience with strong network security expertise.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud security knowledge across AWS, Azure, and GCP.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Engineering/scripting skills in Python, Terraform, Bash, or similar for automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">AI/ML skills to build or integrate AI-assisted automation.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Solid grasp of network design, firewall/ACL remediation, and firewall policy reviews focusing on rule hygiene, least-privilege, and compliance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience automating change management workflows including rule change requests, approvals, validation, and rollback.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Infrastructure-as-Code experience and understanding of CI/CD pipelines.</span></li>\r\n</ul>\r\n<p><span style=\"font-family: Lato, sans-serif;\"><strong>Nice-to-have:</strong></span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">DevSecOps experience.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Advanced automation skills and experience leveraging AI tools for coding and automation.</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Free Health Insurance &ndash; Comprehensive coverage for you and your dependents.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Work-Life Balance &ndash; Flexible work arrangements and realistic workloads to help you maintain a healthy balance.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Healthy Work Culture &ndash; A collaborative, respectful, and growth-oriented environment.</span></li>\r\n<li style=\"font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Provident Fund (PF) and Gratuity benefits as per statutory norms.</span></li>\r\n</ul>',	'2026-08-07',	'2026-09-04',	'published',	155,	8,	'2026-08-07 10:36:32',	'2026-08-15 01:50:23',	'2026-08-07 10:36:32'),
(108,	'AC89',	'AC',	89,	'ADSK-9728',	'Financial Systems Program Manager',	'financial-systems-program-manager',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'5 - 10 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify; text-indent: .5in;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We are seeking a highly organized, execution-oriented Finance Systems Analyst to support Core Finance participation in commercial launches, enterprise system initiatives, and cross-functional transformation projects. This role is not a traditional SAP functional consultant or downstream Finance Systems configuration role. Instead, this individual will serve as an execution partner to the Finance Transformation team, helping reduce the operational burden on Core Finance Subject Matter Experts (SMEs) by owning the tactical work required to successfully support commercial launches, User Acceptance Testing (UAT), and cross-functional project execution.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">The ideal candidate is someone who can take ambiguous conversations and complex projects and create structure, organization, and accountability. They are comfortable working across Finance, Product Management, Engineering, Program Management, and Accounting &amp; Revenue Operations, ensuring Finance deliverables remain organized, documented, tracked, and completed. This role enables Finance SMEs to focus on strategic business process design, requirements analysis, and decision-making while this individual drives execution.</span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Key Responsibilities</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Commercial Launch &amp; Cross-Functional Execution</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support Finance readiness for commercial product and go-to-market launches.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Coordinate Finance activities across Product Management, Engineering, Finance PMO, and&nbsp; Accounting &amp; Revenue Operations.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Organize Finance deliverables, dependencies, risks, milestones, and open issues throughout project lifecycles.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Track action items, decisions, owners, due dates, and follow-up activities to ensure execution stays on schedule.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Help maintain project momentum by proactively driving outstanding work items to completion.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>User Acceptance Testing (UAT)</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Coordinate internal Finance participation in User Acceptance Testing.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Collect screenshots, testing evidence, validation documentation, and supporting artifacts where needed.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Document defects and coordinate issue resolution within internal team.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support&nbsp; post-deployment validation activities</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">&nbsp;<strong>Documentation &amp; Knowledge Management</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Produce clear meeting notes that capture:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Decisions made</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Open questions</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Risks</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Dependencies</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Action items</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Owners</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Due dates</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Create project trackers and maintain centralized documentation.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Develop process maps, user guides, business continuity documentation, and training materials.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Organize information from multiple stakeholders into concise, actionable documentation.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">&nbsp;<strong>Operational &amp; Project Support</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support Finance transformation initiatives through:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Roadmap coordination</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Process documentation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Data gathering and validation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Status reporting</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Project administration</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ad hoc operational support</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Primary Areas of Focus</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">The primary focus is understanding how commercial business events flow into Finance rather than configuring downstream ERP functionality. The primary objective of this role is reducing execution burden for Finance SMEs by owning operational activities such as:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Finance UAT coordination</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Commercial launch readiness</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-system business validation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Meeting facilitation and documentation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Action item management</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Project coordination</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Process documentation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Screenshot and evidence collection</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">User guide creation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-functional follow-up</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5&ndash;10 years supporting Finance systems, Finance Operations, Business Systems, Program Management, or enterprise transformation initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience supporting enterprise software implementations or commercial product launches.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience coordinating work across multiple business and technical organizations.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience supporting User Acceptance Testing (UAT) and business validation.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience managing project execution activities across multiple concurrent initiatives.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">&nbsp;<strong>Preferred Experience</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong experience in several of the following areas:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Offer-to-Price</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Quote-to-Cash</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Order-to-Cash</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Commercial product launches</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Finance transformation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-system validation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Defect management</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Issue tracking</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Program coordination</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Process mapping</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Business documentation</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">User guide development</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Jira, Azure DevOps, ServiceNow, or similar tracking tools</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">SAP ECC or SAP S/4 (working knowledge preferred&mdash;not configuration expertise)</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Desired Skills &amp; Attributes</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">The ideal candidate demonstrates:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Exceptional organization and follow-through</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to create structure from ambiguity</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong listening skills with the ability to synthesize complex discussions into actionable next steps</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent written communication and documentation skills</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong attention to detail</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to identify risks, gaps, dependencies, and unresolved questions</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Proactive ownership mindset</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Comfortable working independently with minimal direction</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to balance multiple priorities and shifting deadlines</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong collaboration across Core Finance, Product, Engineering, and PMO</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Natural curiosity to understand end-to-end business processes</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong analytical and problem-solving abilities</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Success in This Role</strong></span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">A successful candidate will:</span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Reduce manual execution work for Finance SMEs.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Keep cross-functional projects organized and moving forward.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ensure Finance deliverables are completed on time.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Produce clear documentation that improves team efficiency.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Identify issues before they become project risks.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Help Finance participate effectively in commercial launches and enterprise initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Enable the team to spend more time on strategic business analysis and less time on tactical coordination, documentation, and follow-up.</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-08-11',	'2026-09-08',	'published',	152,	13,	'2026-08-10 18:52:31',	'2026-08-15 00:36:23',	'2026-08-10 18:52:31'),
(109,	'AC91',	'AC',	91,	'ADSK-9579',	'Senior Network DevOps Engineer',	'senior-network-devops-engineer-2',	'United States',	'',	'',	'',	'Remote',	'',	'PST',	'W2 Contract',	'',	'10 - 15 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">We are seeking an experienced <strong>Senior Network DevOps Engineer</strong> to help transform traditional enterprise networking into a modern, automated, cloud-native, and AI-driven infrastructure platform.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\">In this role, you will design, automate, monitor, and optimize large-scale enterprise network environments across on-premises data centers and public cloud platforms. You\'ll collaborate with Network Engineering, Cloud, Security, Platform Engineering, and Architecture teams to build highly scalable, resilient, secure, and self-healing network services using Infrastructure-as-Code (IaC), DevOps practices, and Agentic AI technologies.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Key Responsibilities</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and develop network automation solutions using <strong>Python, Ansible, Terraform, and REST APIs</strong>.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build and maintain Infrastructure-as-Code (IaC) solutions for enterprise networking and cloud infrastructure.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Automate provisioning, configuration management, compliance validation, and remediation workflows.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop reusable automation modules, SDKs, and API integrations.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Implement GitOps and CI/CD pipelines for network and infrastructure deployments.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Design and manage cloud networking across <strong>AWS, Azure, and GCP</strong>, including:</span></li>\r\n<ul style=\"margin-top: 0in;\" type=\"circle\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">VPC/VNET</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Transit Gateway</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">VPN Connectivity</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Load Balancers</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">DNS Services</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud Firewalls</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Direct Connect / ExpressRoute</span></li>\r\n</ul>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build enterprise observability solutions using tools such as Grafana, Prometheus, Splunk, ELK, Dynatrace, OpenTelemetry, and InfluxDB.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Develop AI-powered operational workflows using LLMs, RAG architectures, AI Agents, and ChatOps platforms.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Build intelligent automation for incident response, predictive analytics, and anomaly detection.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Integrate security controls into CI/CD pipelines and support Zero Trust and DevSecOps initiatives.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Partner with cross-functional engineering teams to improve platform reliability, automation, and operational excellence.</span></li>\r\n</ul>',	'<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">5+ years (10+ years preferred) of experience in Enterprise Networking, Cloud Networking, Network Automation, DevOps, or Site Reliability Engineering.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong hands-on experience with <strong>Agentic AI development</strong> and AI-driven automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Expertise in <strong>Python</strong>, <strong>Ansible</strong>, Infrastructure-as-Code, and CI/CD pipelines.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience working with <strong>AWS AgentCore</strong> and cloud-native networking solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong understanding of cloud networking, including AWS, Azure, and/or GCP.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with Git, REST APIs, automation frameworks, and Infrastructure-as-Code tools such as Terraform.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience implementing DevOps and DevSecOps best practices.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Strong troubleshooting, analytical, and problem-solving skills.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Excellent communication and collaboration skills in distributed engineering environments.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Preferred Qualifications</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience with SD-WAN, SASE, enterprise firewalls, wireless networking, and network security automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience integrating observability platforms and monitoring solutions.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Exposure to AI Operations (AIOps), LLMs, RAG frameworks, AI Agents, and intelligent automation platforms.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Familiarity with Zero Trust architecture and security automation.</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Experience building scalable automation frameworks for enterprise infrastructure.</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: Lato, sans-serif;\"><strong>Must-Have Skills</strong></span></p>\r\n<ul style=\"margin-top: 0in;\" type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Agentic AI Development</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Python &amp; Ansible</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">CI/CD &amp; DevOps Automation</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">AWS AgentCore</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Cloud Networking (AWS/Azure/GCP)</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Infrastructure-as-Code (Terraform)</span></li>\r\n<li class=\"MsoNormal\" style=\"text-align: justify; font-family: Lato, sans-serif;\"><span style=\"font-family: Lato, sans-serif;\">Enterprise Network Automation</span></li>\r\n</ul>',	'<p><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</p>\r\n<ul>\r\n<li>We offer healthcare plans, which you may opt into at your own expense.</li>\r\n<li>Sick leave is provided under the state laws applicable to your residence.</li>\r\n<li>Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</li>\r\n<li>Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</li>\r\n</ul>',	'2026-08-14',	'2026-09-11',	'closed',	0,	5,	'2026-08-13 19:49:41',	'2026-08-13 21:49:29',	'2026-08-13 19:49:41'),
(110,	'AC93',	'AC',	93,	'BLCK-6230',	'Lifecycle Marketing Operations Manager',	'lifecycle-marketing-operations-manager',	'United States',	'',	'',	'',	'Remote',	'',	'Any',	'W2 Contract',	'',	'5 - 9 years',	'Based on Experience',	'',	'',	'',	'',	'',	'',	1,	'',	'',	'<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">As a Lifecycle Operations Specialist, you will execute marketing campaigns end-to-end through our client\'s owned lifecycle channels (email, in-app, push, SMS). You will work independently with minimal oversight, partnering with cross-functional teams to deploy campaigns on time and with quality. You\'ll be expected to ramp quickly on our platform stack and operate as a fully autonomous contributor from day one.</span></p>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Role &amp; Responsibilities</strong></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Build and deploy complex multi-message marketing campaigns to global audiences via Iterable and supporting platforms</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Execute audience syncing via segmentation tools and data warehouse queries</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Own QA processes &mdash; ensuring campaigns meet lifecycle deployment standards before publish</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Troubleshoot campaign issues independently (template rendering, audience targeting, event triggers, delivery failures)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Execute time-sensitive communications (SEV emails, compliance notices) with urgency and accuracy</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support international campaign execution across multiple locales; coordinate with localization teams</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Coordinate with cross-functional partners (Product, Creative, Localization, Legal, Analytics, Engineering) on timelines and deliverables</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Communicate proactively with stakeholders on campaign status, timelines, and blockers</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Maintain channel health &mdash; enforce frequency caps, suppression rules, subscription compliance</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Triage and resolve issues as they arise</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Support capacity planning by managing intake volume and communicating timelines</span></li>\r\n</ul>\r\n<p class=\"MsoNormal\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Project Overview</strong></span></p>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Role sits within our client\'s Lifecycle Operations function</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Executes campaigns end-to-end across owned channels: email, in-app, push, and SMS</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Operates as a fully autonomous contributor from day one with minimal oversight</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Tech stack: Iterable (primary ESP), Snowflake, Hightouch, Looker, CDPs, reverse ETL tools</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Campaigns span global and international audiences across multiple locales</span></li>\r\n</ul>',	'<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">5&ndash;7 years in email marketing, campaign management, marketing operations, or lifecycle operations</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Hands-on ESP/marketing automation experience (Iterable strongly preferred; Braze, SFMC, or similar acceptable)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with audience segmentation tools and data pipelines (CDPs, reverse ETL, or similar)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Working knowledge of data warehouses (Snowflake, Hightouch, or similar) for audience queries</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong understanding of customer/merchant lifecycles &mdash; end-to-end, all stages</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Ability to work independently with minimal oversight in a fast-paced environment</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Excellent attention to detail and strong QA instincts</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Cross-functional experience (creatives, engineers, analysts, PMs, marketing managers)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Comfort with HTML (basic edits), Handlebars/template logic, and conditional content</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Strong project management skills &mdash; ability to manage multiple campaigns simultaneously</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">AS/BS degree</span></li>\r\n</ul>\r\n<div class=\"mb1\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><em>Nice-to-Haves:</em></span></div>\r\n<ul class=\"mb1\">\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Basic SQL query writing</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience with Snowflake, Looker, or Hightouch</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">A/B testing and experimentation experience</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Familiarity with template management systems</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience in a matrixed org at scale (100M+ profiles)</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Experience handling urgent/time-sensitive communications in high-stakes environments</span></li>\r\n</ul>',	'<p><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><strong>Accelon Consulting</strong> is a global workforce solutions partner and AI enablement leader, but above all, we are a people‑first organization. Our dual commitment is simple: advancing careers and enabling organizations to thrive in a connected, intelligent future. We know our professionals bring specialized expertise, strategic insight, and immediate impact to every engagement. You&rsquo;re not just filling a seat - you&rsquo;re solving problems, leading change, and driving results. Because of that, we treat every consultant like the professional they are. Our culture is built on respect, transparency, and long‑term growth, offering opportunities to work on high‑impact projects with leading global enterprises. At Accelon, people are supported, achievements are recognized, and careers are built with purpose. To learn more about our culture and what it&rsquo;s like to be part of our team, visit the <a href=\"../../../life-at-accelon/\">Life at Accelon</a> section on our website.</span></p>\r\n<ul>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">We offer healthcare plans, which you may opt into at your own expense.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Sick leave is provided under the state laws applicable to your residence.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Work&ndash;Life Balance &mdash; Flexible work arrangements and realistic workloads that support your well‑being.</span></li>\r\n<li style=\"font-family: Lato, sans-serif; font-size: 10pt;\"><span style=\"font-family: Lato, sans-serif; font-size: 10pt;\">Healthy Work Culture &mdash; A collaborative, respectful, and growth‑oriented environment where people thrive.</span></li>\r\n</ul>',	'2026-08-15',	'2026-09-12',	'published',	16,	13,	'2026-08-14 21:56:27',	'2026-08-15 02:05:35',	'2026-08-14 21:56:27');
